// AUTH · PBKDF2 com sal por conta; não criptografa dados de saúde nem torna este login seguro em produção.
async function passwordHash(password,salt){if(!crypto.subtle)throw Error('Este navegador não oferece criptografia local. Abra o arquivo no Chrome ou Edge atualizado.');const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:100000,hash:'SHA-256'},key,256);return Array.from(new Uint8Array(bits),b=>b.toString(16).padStart(2,'0')).join('')}
function authViewV4(register=false){document.body.classList.remove('logged');$('#sidebar').hidden=true;$('#main').className='';$('#nav').hidden=true;$('#quick').hidden=true;$('#header').innerHTML=`<div class="logo"><svg class="via-symbol" viewBox="0 0 48 48" fill="none" aria-hidden="true"><rect x="1" y="1" width="46" height="46" rx="15" fill="currentColor" opacity=".12"/><path d="M12 13L23 36C24 38 26 37 27 35L37 12" stroke="currentColor" stroke-width="5" stroke-linecap="round"/><circle cx="32.5" cy="23" r="5" fill="currentColor" stroke="var(--card)" stroke-width="2"/></svg><span class="brand-name">via</span></div>${btn(icon('moon'),'toggleTheme()','secondary')}`;$('#main').innerHTML=`<div class="auth"><div class="authmark"><svg class="via-symbol" viewBox="0 0 48 48" fill="none" aria-hidden="true"><rect x="1" y="1" width="46" height="46" rx="15" fill="currentColor" opacity=".12"/><path d="M12 13L23 36C24 38 26 37 27 35L37 12" stroke="currentColor" stroke-width="5" stroke-linecap="round"/><circle cx="32.5" cy="23" r="5" fill="currentColor" stroke="var(--card)" stroke-width="2"/></svg></div><div class="eyebrow">VIA · JORNADA DE EMAGRECIMENTO</div><h1>Sua jornada.<br>No seu ritmo.</h1><p class="muted">Um lugar para cuidar dos seus registros e perceber o caminho que você já fez.</p><section class="card"><div class="switch">${btn('Entrar','authView(false)',register?'secondary':'')}${btn('Criar conta','authView(true)',register?'':'secondary')}</div><form id="authForm">${register?field('name','Seu nome','text','','required maxlength="80" autocomplete="name"'):''}${field('email','E-mail','email','','required autocomplete="username" maxlength="150"')}${field('password','Senha','password','','required minlength="8" maxlength="200" autocomplete="'+(register?'new-password':'current-password')+'"')}${register?field('confirm','Confirmar senha','password','','required minlength="8" autocomplete="new-password"'):check('remember','Lembrar sessão neste navegador',true)}<p id="authError" class="error" role="alert"></p><button class="btn full">${register?'Criar minha conta local':'Entrar no Via'}</button></form></section>${btn('Explorar demonstração →','demoLogin()','secondary full')}${notice('Protótipo local: credenciais e dados ficam neste navegador. localStorage não é armazenamento seguro para produção. Não há recuperação de senha por e-mail.')}</div>`;$('#authForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),email=f.email.trim().toLowerCase(),b=e.target.querySelector('button');b.disabled=true;try{if(register){if(f.password!==f.confirm)throw Error('As senhas precisam ser iguais.');if(Object.values(accounts).some(a=>a.email===email))throw Error('Este e-mail já tem uma conta neste navegador.');const salt=uid(),id=uid(),hash=await passwordHash(f.password,salt);accounts[id]={email,salt,hash,data:blank(f.name.trim())};if(!persist()){delete accounts[id];return}enter(id,true)}else{const found=Object.entries(accounts).find(([,a])=>a.email===email&&!a.demo);if(!found||await passwordHash(f.password,found[1].salt)!==found[1].hash)throw Error('E-mail ou senha incorretos.');enter(found[0],!!f.remember)}}catch(err){$('#authError').textContent=err.message}finally{b.disabled=false}}}
