function currentWeight(){return sorted(appData.weightLog)[0]?.value||+appData.profile.current||0}function pct(){const p=appData.profile,den=p.initial-p.goal;return den?Math.max(0,Math.min(100,(p.initial-currentWeight())/den*100)):0}
