function changePassword(){if(accounts[accountId].demo){toast('A demonstração não usa senha. Crie uma conta para testar.');return}form('Trocar senha',field('old','Senha atual','password','','required autocomplete="current-password"')+field('password','Nova senha','password','','required minlength="8" autocomplete="new-password"')+field('confirm','Confirmar nova senha','password','','required minlength="8" autocomplete="new-password"'),async f=>{const a=accounts[accountId];if(await passwordHash(f.old,a.salt)!==a.hash)throw Error('Senha atual incorreta.');if(f.password!==f.confirm)throw Error('As novas senhas não coincidem.');const old={salt:a.salt,hash:a.hash};a.salt=uid();a.hash=await passwordHash(f.password,a.salt);if(!persist()){Object.assign(a,old);return}closeModal();toast('Senha alterada.')})}
