function weightForm(){form('Registrar peso',field('value','Peso (kg)','number',currentWeight()||'','required min="20" max="500" step="0.1"')+dt(),f=>{if(change(d=>{d.weightLog.push({id:uid(),date:f.date,value:+f.value});d.profile.current=sorted(d.weightLog)[0].value})){closeModal();render()}})}
function chart(){const a=[...appData.weightLog].sort((a,b)=>a.date.localeCompare(b.date));if(!a.length)return empty('Sua primeira pesagem começa o gráfico.');const vals=a.map(x=>x.value),min=Math.min(...vals)-1,max=Math.max(...vals)+1,first=+new Date(a[0].date),span=+new Date(a.at(-1).date)-first||1,pts=a.map(x=>[32+(+new Date(x.date)-first)/span*286,145-(x.value-min)/(max-min)*120]);return `<svg class="chart" viewBox="0 0 350 185" role="img" aria-label="Evolução do peso, de ${fmt(vals[0])} a ${fmt(vals.at(-1))} quilos">${[0,1,2].map(i=>`<line x1="30" y1="${25+i*60}" x2="325" y2="${25+i*60}" stroke="var(--line)"/><text x="2" y="${29+i*60}" font-size="10" fill="var(--muted)">${fmt(max-i*(max-min)/2,0)}</text>`).join('')}<polyline points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="var(--green)" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="var(--green)"><title>${date(a[i].date)} · ${fmt(a[i].value)} kg</title></circle>`).join('')}<text x="30" y="177" font-size="11" fill="var(--muted)">${date(a[0].date)}</text><text x="245" y="177" font-size="11" fill="var(--muted)">${date(a.at(-1).date)}</text></svg>`}
function progressViewV4(){let html=`<h1>Seu progresso</h1><p class="muted">Olhe o caminho, além do número.</p>${tabs([['weight','Peso'],['measures','Medidas'],['calendar','Calendário'],['photos','Fotos']],'weight')}`;if(sub==='calendar')return html+calendarView();if(sub==='photos')return html+notice('Simulação de fotos. Câmera e galeria reais virão no Android.')+btn('Adicionar foto simulada','photoForm()','full')+`<div class="grid" style="margin-top:15px">${sorted(appData.photos).map(p=>`<div class="photo">${icon('photo')}<strong>${esc(p.name)}</strong><small>${date(p.date)}</small>${btn('Remover',`removeLog('photos','${p.id}')`,'plain')}</div>`).join('')}</div>`;if(sub==='measures')return html+btn('Registrar medidas','measureForm()','full')+card('Evolução',measureEvolution())+historyList('measurements');let w=currentWeight(),a=sorted(appData.weightLog),delta=a.length>1?w-a[Math.min(a.length-1,3)].value:0;return html+card('Peso ao longo do tempo',`<div class="row"><span class="stat">${w?fmt(w)+' kg':'—'}</span><span class="pill">${fmt(pct(),0)}% da meta</span></div>${chart()}<p class="small muted">${a.length>1?'Variação nas últimas '+Math.min(a.length,4)+' pesagens: '+(delta>0?'+':'')+fmt(delta)+' kg.':'Registre pelo menos duas pesagens para ver uma tendência.'}</p>${btn('Registrar peso','weightForm()','full')}`)+card('',`<div class="grid">${[['Inicial',appData.profile.initial],['Atual',w],['Menor registrado',a.length?Math.min(...a.map(x=>x.value)):0],['Objetivo',appData.profile.goal]].map(([l,v])=>`<div><small>${l}</small><div class="stat">${fmt(v)} <small>kg</small></div></div>`).join('')}</div>`)+card('Histórico de peso',historyList('weightLog'))+menu('calendar','Relatórios e resumo para consulta',"go('reports')")}
function measureForm(){form('Medidas corporais',notice('Campos opcionais, em centímetros. Preencha pelo menos um.')+dt()+['cintura','abdomen','quadril','peito','braco','coxa'].map((k,i)=>field(k,['Cintura','Abdômen','Quadril','Peito','Braço','Coxa'][i]+' (cm)','number','','min="1" max="400" step="0.1"')).join(''),f=>{let vals=Object.fromEntries(['cintura','abdomen','quadril','peito','braco','coxa'].filter(k=>f[k]).map(k=>[k,+f[k]]));if(!Object.keys(vals).length)throw Error('Preencha uma medida.');if(change(d=>d.measurements.push({id:uid(),date:f.date,...vals}))){closeModal();render()}})}
function measureEvolution(){return ['cintura','abdomen','quadril','peito','braco','coxa'].map(k=>{let a=sorted(appData.measurements).filter(x=>x[k]);return a.length?`<div class="row item"><span>${esc(k)}</span><span>${fmt(a[0][k])} cm ${a.length>1?`<small>(${fmt(a[0][k]-a.at(-1)[k])} cm)</small>`:''}</span></div>`:''}).join('')||empty('Registre medidas para acompanhar mudanças.')}
function photoFormV4(){form('Foto simulada',field('name','Legenda','text','','required maxlength="80"')+dt(),f=>{if(change(d=>d.photos.push({id:uid(),...f}))){closeModal();render()}})}
// CALENDAR / NOTES · Todas as séries compartilham data/hora local ISO.
const LOG_LABEL={weightLog:'Peso',measurements:'Medidas',water:'Água',meals:'Refeição',injections:'Aplicação',symptoms:'Sintoma',wellbeing:'Bem-estar',sleep:'Sono',exercises:'Exercício',workouts:'Treino',notes:'Nota',exams:'Exame',otherMeds:'Outro medicamento',photos:'Foto simulada',userTreatments:'Tratamento'};
function logText(k,x){switch(k){case 'weightLog':return fmt(x.value)+' kg';case 'water':return fmt(x.ml,0)+' ml';case 'injections':return `${x.medicine} · ${x.dose} ${x.unit} · ${siteName(x.site)}`;case 'symptoms':return `${x.name} · ${x.severity}${x.note?' · '+x.note:''}`;case 'notes':return x.text;case 'meals':return x.name+' · '+fmt(mealTotals([x]).kcal,0)+' kcal';case 'measurements':return Object.entries(x).filter(([k])=>!['date','id'].includes(k)).map(([k,v])=>k+': '+fmt(v)+' cm').join(' · ');case 'exercises':case 'workouts':return `${x.name} · ${fmt(x.duration)} min${x.feedback?' · '+x.feedback:''}`;case 'sleep':return `${x.bed} → ${x.wake} · ${fmt(x.duration)} h · ${x.feeling}`;case 'wellbeing':return `Humor ${x.mood}/5 · energia ${x.energy}/5 · estresse ${x.stress}/5 · sono ${x.quality}/5 · ${x.note||''}`;case 'exams':return `${x.name}: ${x.value} ${x.unit} · ref. ${x.reference||'não informada'}`;case 'userTreatments':return `${MEDS.find(m=>m.id===x.medId)?.brand||'Medicamento'} · ${x.dose} ${x.unit} · ${x.paused?'Pausado':x.ended?'Encerrado':'Cadastrado'}`;default:return [x.name,x.dose,x.hour,x.note].filter(Boolean).join(' · ')}}
function historyList(k,items=appData[k],limit=100){return sorted(items).slice(0,limit).map(x=>`<div class="item"><small>${when(x.date)}</small><div>${esc(logText(k,x))}</div><div class="row">${k==='meals'?btn('Editar',`editMeal('${x.id}')`,'plain'):''}${btn('Excluir',`removeLog('${k}','${x.id}')`,'plain small')}</div></div>`).join('')||empty('Nenhum registro por aqui ainda.')}
function removeLog(k,id){confirmBox('Excluir registro?','Este registro será apagado do histórico. As outras informações serão mantidas.',()=>{if(change(d=>{d[k]=d[k].filter(x=>x.id!==id);if(k==='injections')Object.keys(d.mapMarkings).forEach(s=>{if(d.mapMarkings[s]===id)delete d.mapMarkings[s]});if(k==='weightLog')d.profile.current=sorted(d.weightLog)[0]?.value||d.profile.initial})){closeModal();render()}})}
function allEvents(){return Object.entries(LOG_LABEL).flatMap(([k,label])=>(appData[k]||[]).map(x=>({...x,kind:k,label}))).sort((a,b)=>b.date.localeCompare(a.date))}
function calendarView(){let y=calendarMonth.getFullYear(),m=calendarMonth.getMonth(),days=new Date(y,m+1,0).getDate(),offset=(new Date(y,m,1).getDay()+6)%7,events=new Set(allEvents().map(x=>x.date.slice(0,10)));return card('',`<div class="row">${btn('‹','monthStep(-1)','secondary')}<strong>${calendarMonth.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</strong>${btn('›','monthStep(1)','secondary')}</div><div class="cal" style="margin-top:18px">${['S','T','Q','Q','S','S','D'].map(x=>`<small>${x}</small>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:days},(_,i)=>{let d=day(new Date(y,m,i+1));return `<button class="${d===calendarDate?'sel':''} ${events.has(d)?'has':''}" aria-label="${date(d)}${events.has(d)?', com registros':''}" onclick="calendarSelect('${d}')">${i+1}</button>`}).join('')}</div>`)+`<div id="calendarEvents"></div>`}
function monthStep(n){calendarMonth.setMonth(calendarMonth.getMonth()+n);render()}function calendarSelect(d){calendarDate=d;render()}
function calendarEvents(){$('#calendarEvents').innerHTML=card(date(calendarDate),allEvents().filter(x=>x.date.slice(0,10)===calendarDate).map(x=>`<div class="item"><small>${x.date.slice(11,16)} · ${x.label}</small><div>${esc(logText(x.kind,x))}</div></div>`).join('')||empty('Um dia em branco também faz parte.'))}
function noteForm(){form('Como foi seu dia?',dt()+area('text','Sua nota'),f=>{if(!f.text.trim())throw Error('Escreva uma nota antes de salvar.');if(change(d=>d.notes.push({id:uid(),...f}))){closeModal();render()}})}function notesView(){return '<h1>Seu diário</h1>'+btn('Adicionar nota','noteForm()','full')+card('',historyList('notes'))}
