for(const f of FOOD_ADDITIONS){const i=FOODS.findIndex(x=>x.id===f.id);if(i>=0)FOODS[i]=f;else FOODS.push(f)}

for(const f of [{id:'rap10',name:'Rap10 Tradicional',group:'cereal',kcal:274,protein:8.2,carbs:45,fat:6.9,fiber:2.7,servings:[{name:'unidade (rótulo)',g:33}],source:'Rótulo oficial Rap10 Tradicional · consultado 07/09/2026',url:'https://www.rap10.com.br/'},{id:'reqlight',name:'Requeijão cremoso light Tirolez',group:'proteina',kcal:187,protein:8.5,carbs:2.2,fat:16,fiber:0,servings:[{name:'colher de chá (estimada)',g:5},{name:'colher de sopa (rótulo)',g:20}],source:'Rótulo oficial Tirolez: 30 g = 1½ colher de sopa. Colher de chá estimada em 5 g.',url:'https://www.tirolez.com.br/produtos/nutricao-bem-estar/requeijao-cremoso-light/'},{id:'gomatapioca',name:'Goma de tapioca hidratada Amafil',group:'cereal',kcal:232,protein:0,carbs:58,fat:0,fiber:0,servings:[{name:'colher de sopa rasa (rótulo)',g:10},{name:'colher de sopa cheia (estimada)',g:20}],source:'Rótulo Amafil: porção 20 g (2 colheres de sopa). Colher cheia é estimada; calibre a sua.',url:'https://amafil.com.br/'}])FOODS.push({...f,base:100,measure:'100 g',unit:'g',micro:{},tags:f.group==='proteina'?['proteina']:[]});
function servingsV2(f){if(!f.servings)return servingsLegacy(f);return [...f.servings,{name:f.unit==='ml'?'mililitro':'grama',g:1}].map(s=>({...s,g:appData.servingCalibration.find(c=>c.foodId===f.id&&c.measure===s.name)?.grams||s.g}))}
function foodViewV2(){let h=foodViewLegacy();h=h.replace("</div>","</div>");const tab=btn('Receitas',"go('food','recipes')",sub==='recipes'?'':'secondary');if(sub==='recipes')return `<div class="v2-head"><div><h1>Receitas</h1><p class="muted">Ingredientes de verdade. Porções do seu jeito.</p></div>${btn('+ Adicionar receita','newRecipe()')}</div>${tabs([['today','Hoje'],['search','Buscar'],['pantry','Meus alimentos'],['meals','Refeições'],['recipes','Receitas'],['nutrition','Nutrição']],'recipes')}${field('recipequery','Buscar receita','search','','placeholder="Pão com ovo, café com leite, Rap10…" oninput="recipeSearch()"')}<div id="recipeResults"></div>`;h=h.replace('</h1>','</h1>'+`<div style="margin:12px 0">${tab} ${btn('+ Adicionar receita','newRecipe()','plain')}</div>`);return h}
function foodSearchV2(){foodSearchLegacy();const root=$('#foodResults');root.innerHTML=root.innerHTML.replace(/(<div class="row item">[\s\S]*)(<button class="btn plain"[^>]*onclick="customFoodForm\(\)"[\s\S]*)$/, '<div class="food-results-grid">$1</div>$2');for(const f of foodAll()){if(!f.servings)continue;const s=servings(f)[0];root.innerHTML=root.innerHTML.replace(`${fmt(f.kcal,0)} kcal · ${esc(f.measure)} (${fmt(f.base)} ${f.unit})`,`${fmt(f.kcal*s.g/f.base,0)} kcal · ${esc(s.name)} (${fmt(s.g)} ${f.unit})`)}}
const RECIPE_BASES=[['cafe-leite','Café com leite',[['cafe',100],['leite',100]]],['ovos','Dois ovos cozidos',[['ovo',100]]],['pao-ovo','Pão francês com ovo cozido',[['frances',50],['ovo',50]]],['pao-queijo','Pão francês com requeijão e queijo',[['frances',50],['requeijao',5],['mussarela',20]]],['rap-frango','Rap10 de frango com requeijão light',[['rap10',33],['reqlight',10],['desfiado',45],['rucula',10]]],['tapioca','Tapioca com requeijão, tomate e alface',[['gomatapioca',60],['requeijao',10],['tomate',30],['alface',10]]],['integral','Sanduíche integral de frango',[['paointegral',50],['desfiado',45],['reqlight',5],['alface',10]]],['cafe-bolacha','Café e bolacha de sal',[['cafe',50],['cracker',24]]],['massinha','Pão massinha com queijo',[['massinha',50],['minas',30]]],['doce','Café com bolacha doce',[['cafe',50],['maisena',24]]]];
function allRecipes(){return [...RECIPE_BASES.map(([id,name,parts])=>({id:'base_'+id,name,base:true,yield:1,portion:'porção',instructions:'Quantidades iniciais para editar. Inclua açúcar, óleo e outros ingredientes que você usar.',items:parts.map(([id,g])=>{const f=foodBy(id),s=servings(f)[0];return makeItem(f,g/s.g,s.g,s.name)})})),...appData.recipes]}
function recipeBy(id){return allRecipes().find(x=>x.id===id)}
function scaledItems(items,factor){if(!Number.isFinite(factor)||factor<=0)throw Error('Informe uma quantidade válida.');return items.map(i=>({...clone(i),id:uid(),qty:i.qty*factor,...Object.fromEntries(['kcal','protein','carbs','fat','fiber'].map(k=>[k,i[k]*factor])),micro:Object.fromEntries(Object.entries(i.micro||{}).map(([k,v])=>[k,v*factor]))}))}
function recipeSearch(){const q=norm($('#f_recipequery')?.value||'');$('#recipeResults').innerHTML=`<p class="small muted">${allRecipes().length} receitas disponíveis · bases editáveis e suas criações</p><div class="recipe-grid">${allRecipes().filter(r=>norm(r.name+' '+r.items.map(i=>i.name).join(' ')).includes(q)).map(r=>`<article class="recipe-card"><span class="pill">${r.base?'Base para personalizar':'Minha receita'}</span><h3>${esc(r.name)}</h3><p class="small muted">${r.items.length} ingredientes · rende ${fmt(r.yield)} ${esc(r.portion)}</p>${macroView(mealTotals([{items:scaledItems(r.items,1/r.yield)}]))}${btn('Ver ingredientes →',`recipeDetail('${r.id}')`,'secondary full')}</article>`).join('')}</div>`}
function recipeDetailV2(id){const r=recipeBy(id);modal(esc(r.name),`<small>Receita inteira · rende ${fmt(r.yield)} ${esc(r.portion)}</small>${r.items.map(i=>`<div class="item row"><div><strong>${esc(i.name)}</strong><small>${fmt(i.qty)} × ${esc(i.measure)} · ${fmt(i.qty*i.grams)} ${foodBy(i.foodId)?.unit||'g'}</small></div><span>${fmt(i.kcal)} kcal</span></div>`).join('')}${macroView(mealTotals([r]))}<p class="small muted">${esc(r.instructions)}</p>${notice('Valores aproximados. As colheres variam: calibre suas medidas ou informe gramas. Somamos apenas os ingredientes informados.')}${btn('Registrar consumo',`consumeRecipe('${id}')`,'full')}${btn(r.base?'Personalizar e salvar':'Editar receita',`editRecipe('${id}')`,'secondary full')}${!r.base?btn('Excluir receita',`deleteRecipe('${id}')`,'plain full'):''}`)}
function setDraftV2(d){const apply=()=>{draftMeal=d;mealEditor()};if(draftMeal?.items.length)confirmBox('Substituir rascunho?','Há uma refeição ou receita em edição. Substituir este rascunho?',apply);else apply()}
function newRecipe(){setDraft({id:uid(),date:stamp(),name:'',mode:'recipe',yield:1,portion:'porção',items:[],instructions:''})}
function editRecipe(id){const r=clone(recipeBy(id));setDraft({...r,id:r.base?uid():r.id,date:r.date||stamp(),base:false,editing:!r.base,mode:'recipe'})}
function stashMeal(){stashMealLegacy();if(draftMeal?.mode==='recipe'){if($('#f_recipeYield'))draftMeal.yield=+$('#f_recipeYield').value;if($('#f_recipePortion'))draftMeal.portion=$('#f_recipePortion').value;if($('#f_instructions'))draftMeal.instructions=$('#f_instructions').value}}
function mealEditorV2(){if(draftMeal?.mode!=='recipe')return mealEditorLegacy();const d=draftMeal;form(d.editing?'Editar receita':'Adicionar receita',field('name','Nome da receita','text',d.name,'required maxlength="80" placeholder="Rap10 de frango com requeijão"')+`<div class="grid"><div>${field('recipeYield','Rende quantas porções?','number',d.yield,'required min="0.1" max="1000" step="0.1"')}</div><div>${field('recipePortion','Nome da porção','text',d.portion,'required maxlength="40"')}</div></div>`+d.items.map((i,n)=>`<div class="item"><strong>${esc(i.name)}</strong><small>${fmt(i.qty)} × ${esc(i.measure)} · ${fmt(i.kcal)} kcal</small><div class="row">${btn('Editar porção',`stashMeal();foodPortion('${i.foodId}',${n})`,'plain')}${btn('Retirar',`stashMeal();draftMeal.items.splice(${n},1);mealEditor()`,'plain')}</div></div>`).join('')+btn('+ Adicionar ingrediente',"stashMeal();closeModal();go('food','search')",'secondary full')+'<div id="recipeLive" class="recipe-summary"></div>'+area('instructions','Preparo / observações',d.instructions||'')+btn('Descartar rascunho','discardMeal()','plain'),v=>{if(!d.items.length)throw Error('Adicione ao menos um ingrediente.');const r={id:d.id,date:d.date,name:v.name.trim(),yield:+v.recipeYield,portion:v.recipePortion,items:clone(d.items),instructions:v.instructions};if(!r.name||!Number.isFinite(r.yield)||r.yield<=0)throw Error('Confira nome e rendimento.');if(change(a=>{const i=a.recipes.findIndex(x=>x.id===r.id);if(i>=0)a.recipes[i]=r;else a.recipes.push(r)},'Receita salva; consumo não lançado.')){draftMeal=null;persistDraft();closeModal();go('food','recipes')}},'Salvar receita');const update=()=>{const y=+$('#f_recipeYield').value;$('#recipeLive').innerHTML=`<small>Receita inteira</small>${macroView(mealTotals([d]))}${y>0?'<small>Por porção</small>'+macroView(mealTotals([{items:scaledItems(d.items,1/y)}])):''}`};$('#f_recipeYield').oninput=update;update()}
function consumeRecipe(id){const r=recipeBy(id);form('Registrar consumo',`<h3>${esc(r.name)}</h3>${field('recipeQty','Porções consumidas','number',1,'required min="0.1" max="1000" step="0.1"')}${dt()}<div id="consumeTotals"></div>`,v=>{const items=scaledItems(r.items,+v.recipeQty/r.yield);if(change(d=>d.meals.push({id:uid(),date:v.date,name:(r.name+' · '+v.recipeQty+' '+r.portion).slice(0,100),recipeId:r.id,items}))){closeModal();go('food','today')}},'Registrar refeição');const update=()=>{const q=+$('#f_recipeQty').value;$('#consumeTotals').innerHTML=q>0?macroView(mealTotals([{items:scaledItems(r.items,q/r.yield)}])):''};$('#f_recipeQty').oninput=update;update()}
function deleteRecipe(id){confirmBox('Excluir receita?','Refeições já registradas serão preservadas.',()=>{if(change(d=>d.recipes=d.recipes.filter(x=>x.id!==id))){closeModal();render()}})}

const POINTS=[['abdomen_v2_1',40.87,33.51,'1'],['abdomen_v2_2',58.91,33.51,'2'],['abdomen_v2_3',58.91,40,'3'],['abdomen_v2_4',40.87,40,'4'],['arm_right',16.3,26.65,'D'],['arm_left',83.7,26.65,'E'],['thigh_right',29.13,59.77,'D'],['thigh_left',70.65,59.77,'E']];
const VALID_SITES=[...POINTS.map(x=>x[0]),...Array.from({length:8},(_,i)=>'abdomen_'+(i+1))];
function siteName(s){return s?.startsWith('abdomen_v2_')?'Abdômen · ponto '+s.split('_')[2]:s?.startsWith('abdomen_')?'Abdômen · mapa antigo · ponto '+s.split('_')[1]:({arm_left:'Braço esquerdo',arm_right:'Braço direito',thigh_left:'Coxa esquerda',thigh_right:'Coxa direita',oral:'Registro oral'})[s]||'Local não informado'}
function injectionTips(){return `<ol><li>Lave as mãos e prepare o material em uma superfície limpa.</li><li>Quando o produto for um <strong>frasco com tampa de borracha</strong>, limpe a tampa com álcool 70% e deixe secar antes de perfurar. Siga as instruções específicas da embalagem.</li><li>Higienize a pele com algodão ou gaze e álcool 70%, deixando secar. Evite tocar novamente no local limpo.</li><li>Use <strong>agulha e seringa novas, estéreis, em cada aplicação</strong>. Não reutilize nem compartilhe. Em canetas, siga a bula sobre troca de agulha.</li><li>Alterne as regiões conforme a bula e orientação recebida. Não aplique sobre pele irritada, endurecida ou machucada.</li><li>Descarte o material perfurocortante em recipiente apropriado. Confira conservação, validade e aparência do produto.</li></ol><a class="source-link" href="https://www.cdc.gov/injection-safety/hcp/clinical-safety/index.html" target="_blank" rel="noopener">Cuidados gerais: CDC ↗</a><p class="small muted">Estas dicas complementam o treinamento com sua equipe. Não orientam retirada de medicamento de canetas nem preparo de formulações.</p>`}
function mapView(){const marked=Object.values(appData.mapMarkings),latest=sorted(appData.injections.filter(x=>marked.includes(x.id)))[0]?.id;return notice('Quatro posições no abdômen para registrar sua escolha. Direita/esquerda são do seu corpo. O desenho é esquemático: siga a bula para regiões e distância do umbigo. Braços indicam região posterior/lateral.')+`<div class="map-panels">${card('Seu mapa de aplicações',`<div class="bodymap v2-map"><svg class="body" viewBox="293 150 460 1310" role="img" aria-label="Manequim da imagem enviada, com quatro pontos abdominais"><defs><clipPath id="bodyClip"><path d="M520 153C454 152 451 230 470 283L481 326 463 348C392 359 366 380 355 451L332 565 308 635 290 716 279 838 300 886 329 906 340 883 327 784 387 655 405 545 407 660 386 789 388 909 420 1090 427 1200 389 1402Q374 1451 425 1455L455 1444 486 1299 505 1136 520 956 539 1136 552 1299 585 1444Q639 1474 654 1433L619 1240 614 1130 652 940 657 802 638 693 637 567 658 683 711 788 706 854 711 900 735 879 749 840 725 748 717 624 694 560 692 464C679 377 656 363 586 348L571 326 575 286C605 227 599 155 520 153Z"/></clipPath></defs><image href="${MANNEQUIN_DATA}" x="0" y="0" width="1055" height="1491" clip-path="url(#bodyClip)"/></svg>${POINTS.map(([id,x,y,l])=>`<button id="${id}" class="point ${appData.mapMarkings[id]?(appData.mapMarkings[id]===latest?'recent':'old'):''}" style="left:${x}%;top:${y}%" aria-label="${siteName(id)}" onclick="pointClick('${id}')">${l}</button>`).join('')}</div><div class="legend"><span style="--dot:#dbe3de">Sem marcação</span><span style="--dot:#53a580">Uso anterior</span><span style="--dot:#edb260">Mais recente</span></div>${btn('Limpar marcações','clearMap()','plain full')}<small>Limpar o mapa preserva o histórico. Marcações do antigo mapa de oito pontos permanecem apenas no histórico.</small>`)}<div>${card('Cuidados práticos',injectionTips())}${card('mg, ml e UI',`<p>Confira a relação entre a dose já prescrita, a concentração e o volume.</p>${syringeSvg(null,30)}${btn('Conferir medidas','syringeCalculator()','secondary full')}`)}${card('Aplicações recentes',sorted(appData.injections).slice(0,5).map(x=>`<div class="item small">${when(x.date)}<br>${esc(siteName(x.site))}<br>${esc(x.medicine)} · ${esc(x.dose)} ${esc(x.unit)}</div>`).join('')||empty('Nenhuma aplicação registrada.'))}</div></div>`}
function syringeMath(dose,concentration,capacity=30){if(![dose,concentration,capacity].every(Number.isFinite)||dose<=0||concentration<=0||![30,50,100].includes(capacity))throw Error('Informe dose e concentração positivas e uma capacidade válida.');const ml=dose/concentration,ui=ml*100;if(ui>capacity)throw Error('O volume calculado excede a capacidade desta seringa. Confira os dados com o profissional; não divida nem adapte a dose pelo aplicativo.');return {ml,ui}}
function syringeSvgV2(ui,capacity){return `<svg class="syringe" viewBox="0 0 520 125" role="img" aria-label="Diagrama de seringa U-100 de ${capacity} unidades${ui===null?'':', resultado matemático '+fmt(ui,6)+' unidades'}"><path d="M15 64H65M65 52H80V76H65ZM80 38H430V90H80Z M430 30V98M435 61H485V68H435M486 45V85" fill="none" stroke="currentColor" stroke-width="2"/>${ui!==null?`<rect x="82" y="40" width="${346*ui/capacity}" height="48" fill="var(--blue)" opacity=".25"/>`:''}${Array.from({length:capacity+1},(_,i)=>{const x=82+i*346/capacity;return `<path d="M${x} 40v${i%5===0?20:10}" stroke="currentColor"/>${i%5===0?`<text x="${x}" y="24" text-anchor="middle" font-size="12" fill="currentColor">${i}</text>`:''}`}).join('')}<text x="255" y="118" text-anchor="middle" font-size="12" fill="currentColor">U-100 · ${capacity} UI = ${fmt(capacity/100,2)} ml · desenho ilustrativo</text></svg>`}
function syringeCalculatorV2(){form('Conferir mg, ml e UI',notice('Não existe equivalência fixa entre mg e UI. Esta calculadora confere matemática; não escolhe dose nem substitui a confirmação do profissional. Use apenas a concentração final que consta no rótulo/orientação, sem estimar diluição.')+field('dose','Dose já prescrita (mg)','number','','required min="0.000001" step="any"')+field('concentration','Concentração final confirmada (mg/ml)','number','','required min="0.000001" step="any"')+select('capacity','Capacidade da seringa U-100',[[30,'30 UI · 0,3 ml'],[50,'50 UI · 0,5 ml'],[100,'100 UI · 1 ml']],30)+check('confirmed','Confirmei a concentração e que a seringa é U-100',false)+'<div id="syringeResult">'+syringeSvg(null,30)+'</div>',v=>{if(!v.confirmed)throw Error('Confirme a concentração e a escala U-100.');const r=syringeMath(+v.dose,+v.concentration,+v.capacity);$('#syringeResult').innerHTML=`<div class="recipe-summary"><strong>${fmt(+v.dose,6)} mg ÷ ${fmt(+v.concentration,6)} mg/ml</strong><h2>${fmt(r.ml,6)} ml = ${fmt(r.ui,6)} UI na escala U-100</h2><small>Resultado matemático. A graduação real pode não permitir medir esse valor: confirme antes de usar. Não arredonde a dose por conta própria.</small></div>${syringeSvg(r.ui,+v.capacity)}`},'Calcular');for(const id of ['dose','concentration','capacity'])$('#f_'+id).addEventListener('input',()=>{$('#syringeResult').innerHTML=syringeSvg(null,+$('#f_capacity').value);$('#formError').textContent=''});$('#f_confirmed').addEventListener('change',()=>{$('#syringeResult').innerHTML=syringeSvg(null,+$('#f_capacity').value)});}

