const FOOD_CATEGORIES=['Bebidas','Frutas','Verduras e legumes','Carnes e ovos','Pães, cereais e tubérculos','Laticínios','Leguminosas','Óleos e temperos','Outros'];let foodCategory='',foodQuery='',foodScope='all',foodEditDraft=null;
function foodCategoryOf(f){if(f.category)return f.category;if(/queijo|requeij|iogurte/i.test(f.name))return'Laticínios';if(f.unit==='ml'||/café|suco|bebida/i.test(f.name))return'Bebidas';return ({fruta:'Frutas',vegetal:'Verduras e legumes',proteina:'Carnes e ovos',cereal:'Pães, cereais e tubérculos',laticinio:'Laticínios',leguminosa:'Leguminosas',gordura:'Óleos e temperos',tempero:'Óleos e temperos'})[f.group]||'Outros'}
function foodView(){const head=`<div class="v2-head"><div><h1>Alimentação</h1><p class="muted">Monte sua refeição, um ingrediente de cada vez.</p></div>${btn('+ Montar refeição','newMeal()')}</div>${tabs([['today','Hoje'],['search','Adicionar alimentos'],['library','Biblioteca'],['recipes','Receitas'],['pantry','Minha despensa'],['meals','Refeições salvas'],['nutrition','Nutrição']],'today')}`;if(['search','library'].includes(sub))return head+`<div class="section-actions">${btn('+ Cadastrar alimento','customFoodForm()','secondary')}${btn('+ Adicionar receita','newRecipe()','plain')}${btn('Guardar minha biblioteca no backup','exportData()','plain')}</div><div class="food-filters"><div>${field('search','Buscar alimento','search',foodQuery,'placeholder="cafe, café, REPOLHO, azeite…" oninput="foodSearch()"')}</div><div>${select('foodcategory','Categoria',[['','Todas as categorias'],...FOOD_CATEGORIES],foodCategory)}</div><div>${select('foodmode','Mostrar',[['all','Todos'],['custom','Meus cadastros'],['favorites','Favoritos'],['recent','Recentes']],foodScope)}</div></div><div class="food-split"><div id="foodResults"></div><aside class="recipe-summary"><h2>${draftMeal?'Sua montagem':'Comece pela refeição'}</h2>${draftMeal?`<strong>${esc(draftMeal.name||'Sem título')}</strong>${draftMeal.items.map(i=>`<div class="item small">${fmt(i.qty)} × ${esc(i.measure)}<br>${esc(i.name)}</div>`).join('')}${macroView(mealTotals([draftMeal]))}${btn('Continuar / concluir','resumeDraft()','full')}`:`<p class="muted">Dê um nome ao seu café da manhã, almoço ou lanche e vá adicionando os alimentos.</p>${btn('Montar refeição','newMeal()','full')}`}</aside></div>`;if(sub==='today')return head+`<div class="v2-grid">${card('Consumo registrado hoje',macroView(mealTotals(today(appData.meals)))+btn('+ Registrar refeição','newMeal()','full'))}${card('Receitas e pratos compostos',`<p>Saladas, acompanhamentos, café com complementos… salve seus ingredientes para repetir depois.</p>${btn('Abrir minhas receitas',"go('food','recipes')",'secondary full')}`)}</div>`+today(appData.meals).map(m=>card(esc(m.name),`<small>${when(m.date)}</small>${m.items.map(i=>`<div class="item small">${fmt(i.qty)} × ${esc(i.measure)} · ${esc(i.name)}</div>`).join('')}${macroView(mealTotals([m]))}${btn('Editar refeição',`editMeal('${m.id}')`,'secondary')}`)).join('');let old=foodViewV2();return head+(sub==='recipes'?btn('+ Adicionar receita','newRecipe()','secondary'):'')+old.slice(old.indexOf('</div>',old.indexOf('class="tabs"'))+6)}
function foodSearch(){foodQuery=$('#f_search')?.value||'';foodCategory=$('#f_foodcategory')?.value||'';foodScope=$('#f_foodmode')?.value||'all';for(const id of ['foodcategory','foodmode'])if($('#f_'+id))$('#f_'+id).onchange=foodSearch;const q=norm(foodQuery),recent=new Set(appData.meals.slice(-10).flatMap(m=>m.items.map(i=>i.foodId)));const foods=foodAll().filter(f=>norm(f.name+' '+(f.aliases||'')).includes(q)&&(!foodCategory||foodCategoryOf(f)===foodCategory)&&(foodScope==='all'||foodScope==='custom'&&[...appData.customFoods,...appData.foodEdits].some(x=>x.id===f.id)||foodScope==='favorites'&&appData.favoriteFoods.includes(f.id)||foodScope==='recent'&&recent.has(f.id)));$('#foodResults').innerHTML=`<p class="small muted">${foods.length} alimentos · a busca aceita com ou sem acentos</p><div class="food-library">${foods.map(f=>{const m=servings(f)[0];return `<article class="food-entry"><span class="food-chip">${esc(foodCategoryOf(f))}</span><h3>${esc(f.name)}</h3><small>${fmt(m.g)} ${esc(f.unit)} · ${esc(m.name)}</small><small>${f.missing?.includes('kcal')?'Calorias não informadas':fmt(f.kcal*m.g/f.base,0)+' kcal aproximadas'}</small><div class="row">${btn('Adicionar',`foodPortion('${f.id}')`)}${btn('Editar',`customFoodForm('${f.id}')`,'plain')}<button class="circle" aria-label="Favoritar ${esc(f.name)}" onclick="favoriteFood('${f.id}')">${appData.favoriteFoods.includes(f.id)?'★':'☆'}</button></div></article>`}).join('')}</div>${foods.length?'':empty('Não encontrou? Cadastre pelo botão + acima.')}`}
function servings(f){if(f.unit==='gota')return f.servings||[{name:'gota',g:1}];return servingsV2(f)}
function foodPortion(id,editIndex=null){const f=foodBy(id);if(!f)return;const ss=servings(f),old=editIndex===null?null:draftMeal.items[editIndex];const supplements=[['acucar','Açúcar · colheres de chá',4],['adocante_generico','Adoçante genérico · gotas',1],['leite','Leite desnatado · ml',1],['azeite','Azeite · colheres de chá',4],['sal','Sal · pitadas',.3],['limao','Limão · colheres de chá',5]].filter(x=>x[0]!==id);form(esc(f.name),`<span class="food-chip">${esc(foodCategoryOf(f))}</span>${select('measure','Medida utilizada',ss.map((x,i)=>[i,`${x.name} · ${fmt(x.g)} ${f.unit}`]),Math.max(0,ss.findIndex(s=>s.name===old?.measure)))}${field('qty','Quantidade','number',old?.qty||1,'required min="0.1" max="10000" step="0.1"')}<div id="portionResult"></div>${!old?`<details class="complements"><summary>Adicionou algum complemento?</summary><p class="small muted">Preencha apenas o que usou. Zero = não adicionar.</p>${supplements.map(([k,label])=>`<div class="complement-row">${field('extra_'+k,label,'number',0,'min="0" max="10000" step="0.1"')}</div>`).join('')}<small>Outros complementos podem ser adicionados como alimentos.</small></details>`:''}<details><summary class="small">Referência e medidas</summary><p class="small">${esc(f.source)}</p>${btn('+ Cadastrar outra medida',`customFoodForm('${id}')`,'plain')}</details>`,v=>{if(!draftMeal)draftMeal={id:uid(),name:'Minha refeição',date:stamp(),items:[]};const m=ss[+v.measure],it=makeItem(f,+v.qty,m.g,m.name);if(old){it.id=old.id;it.parentId=old.parentId;draftMeal.items[editIndex]=it}else{draftMeal.items.push(it);for(const[k,label,g]of supplements){const q=+v['extra_'+k]||0;if(q>0)draftMeal.items.push({...makeItem(foodBy(k),q,g,label.split(' · ')[1]),parentId:it.id})}}persistDraft();mealEditor()},old?'Atualizar quantidade':'Adicionar à montagem');const update=()=>{const m=ss[+$('#f_measure').value],it=makeItem(f,+$('#f_qty').value||0,m.g,m.name);let items=[it];if(!old)for(const[k,label,g]of supplements){const q=+$('#f_extra_'+k)?.value||0;if(q)items.push(makeItem(foodBy(k),q,g,label))}$('#portionResult').innerHTML=macroView(mealTotals([{items}]))+`<small>Alimento principal: ${fmt(it.qty*m.g)} ${esc(f.unit)}</small>`};$('#f_measure').onchange=update;$('#f_qty').oninput=update;if(!old)for(const[k]of supplements)$('#f_extra_'+k).oninput=update;update()}
function customFoodForm(id=null){const f=id?clone(foodBy(id)):null;foodEditDraft=f||{id:uid(),name:'',category:'Outros',type:'natural',unit:'g',base:100,measure:'100 g',servings:[{name:'porção',g:100}],micro:{},tags:[],missing:['kcal','protein','carbs','fat','fiber'],kcal:0,protein:0,carbs:0,fat:0,fiber:0};foodEditDraft.category=foodCategoryOf(foodEditDraft);foodEditDraft.editing=!!id;foodEditDraft.servings=foodEditDraft.servings||servings(foodEditDraft).filter(x=>!['grama','mililitro'].includes(x.name));foodEditForm()}
function stashFoodEdit(){const d=foodEditDraft;if(!d||!$('#f_foodname'))return;for(const[k,id]of Object.entries({name:'foodname',category:'foodcat',type:'foodtype',unit:'foodunit',brand:'foodbrand',prep:'foodprep',aliases:'aliases',source:'foodsource'}))d[k]=$('#f_'+id)?.value||'';d.base=+$('#f_foodbase').value;d.missing=[];for(const k of ['kcal','protein','carbs','fat','fiber']){const v=$('#f_food_'+k).value;if(v==='')d.missing.push(k);d[k]=+v||0}d.micro={};for(const k of Object.keys(NUTRIENTS).filter(k=>!['proteina','fibra'].includes(k))){const v=$('#f_micro_'+k)?.value;if(v!==undefined&&v!=='')d.micro[k]=+v}d.servings=d.servings.map((s,i)=>({name:$('#f_mname_'+i).value,g:+$('#f_mgrams_'+i).value}))}
function foodEditForm(){const d=foodEditDraft;form(d.editing?'Editar cadastro do alimento':'Cadastrar alimento',select('foodtype','Tipo de cadastro',[['natural','Alimento natural / preparado'],['label','Produto com rótulo']],d.type||'natural')+field('foodname','Nome do alimento','text',d.name,'required maxlength="100"')+select('foodcat','Categoria',FOOD_CATEGORIES,d.category)+field('foodprep','Preparo / variante','text',d.prep||'','maxlength="100" placeholder="Cru, cozido sem sal, grelhado…"')+field('aliases','Outros nomes para busca','text',d.aliases||'','maxlength="200" placeholder="Bolacha, biscoito…"')+field('foodbrand','Marca (opcional)','text',d.brand||'','maxlength="80"')+`<div class="grid"><div>${select('foodunit','Unidade de referência',['g','ml','gota'],d.unit)}</div><div>${field('foodbase','Quantidade de referência','number',d.base,'required min="0.1" max="5000" step="0.1"')}</div></div><p class="small muted">Nutrientes abaixo correspondem à quantidade de referência acima. Ex.: 100 g. Deixe em branco o que não souber.</p>`+['kcal','protein','carbs','fat','fiber'].map((k,i)=>field('food_'+k,['Calorias (kcal)','Proteínas (g)','Carboidratos (g)','Gorduras (g)','Fibras (g)'][i],'number',d.missing?.includes(k)?'':d[k],'min="0" max="100000" step="any"')).join('')+`<details><summary>Micronutrientes opcionais</summary>${Object.entries(NUTRIENTS).filter(([k])=>!['proteina','fibra'].includes(k)).map(([k,v])=>field('micro_'+k,v[0]+' ('+v[1]+')','number',d.micro[k]??'','min="0" max="100000" step="any"')).join('')}</details><h3>Minhas medidas caseiras</h3><p class="small">Informe quanto pesa ou contém cada medida, na unidade de referência. Ex.: colher de chá = 4 g.</p>${d.servings.map((s,i)=>`<div class="measure-row"><div>${field('mname_'+i,'Nome da medida','text',s.name,'required maxlength="80"')}</div><div>${field('mgrams_'+i,'Quantidade','number',s.g,'required min="0.1" max="5000" step="any"')}</div>${btn('×',`stashFoodEdit();foodEditDraft.servings.splice(${i},1);foodEditForm()`,'plain')}</div>`).join('')}${btn('+ Adicionar medida',"stashFoodEdit();foodEditDraft.servings.push({name:'',g:1});foodEditForm()",'secondary full')}${field('foodsource','Fonte / observação','text',d.source||'Informado pelo usuário','maxlength="300"')}${notice('Editar um alimento muda as próximas montagens. Refeições já registradas preservam os valores que tinham.')}`,()=>{stashFoodEdit();const f=clone(foodEditDraft);if(!f.name.trim()||!f.servings.length||f.servings.some(s=>!s.name.trim()||!(s.g>0)))throw Error('Preencha o nome e ao menos uma medida válida.');f.measure=f.unit==='gota'?'gota':'porção de referência';f.group=f.category==='Bebidas'?'bebida':f.group||'personalizado';f.source=f.source||'Informado pelo usuário';delete f.editing;if(change(a=>{const list=FOODS.some(x=>x.id===f.id)?a.foodEdits:a.customFoods;const i=list.findIndex(x=>x.id===f.id);if(i>=0)list[i]=f;else list.push(f);a.servingCalibration=a.servingCalibration.filter(x=>x.foodId!==f.id);if(!a.foods.includes(f.id))a.foods.push(f.id)})){foodEditDraft=null;closeModal();go('food','library')}},'Salvar na minha biblioteca')}
function exportPersonalHTML(){const lib={foods:appData.customFoods,edits:appData.foodEdits,recipes:appData.recipes};const encoded=JSON.stringify(lib).replace(/</g,'\\u003c');const scripts=[...document.scripts].filter(s=>s.id!=='portableLibrary').map(s=>s.outerHTML).join('\n');const style=[...document.querySelectorAll('style')].map(s=>s.outerHTML).join('\n');const h='<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Via 4 · Minha biblioteca</title>'+style+'</head><body>'+APP_SHELL_V3+'<script id="portableLibrary" type="application/json">'+encoded+'</scr'+'ipt>'+scripts+'</body></html>';const url=URL.createObjectURL(new Blob([h],{type:'text/html'})),a=document.createElement('a');a.href=url;a.download='via-v4-minha-biblioteca.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('HTML exportado com alimentos e receitas; sem contas, exames ou registros de consumo.')}
function importPortableLibrary(d){const e=document.getElementById('portableLibrary');if(!e||d.portableImported)return;try{const lib=JSON.parse(e.textContent);for(const f of lib.foods||[])if(!d.customFoods.some(x=>x.id===f.id)&&!FOODS.some(x=>x.id===f.id))d.customFoods.push(f);for(const f of lib.edits||[])if(!d.foodEdits.some(x=>x.id===f.id))d.foodEdits.push(f);for(const r of lib.recipes||[])if(!d.recipes.some(x=>x.id===r.id))d.recipes.push(r);d.portableImported=true}catch{}}

let examDraft=null;
function examsView(){return `<div class="v2-head"><div><h1>Exames</h1><p class="muted">Um atendimento, vários resultados. Tudo no mesmo lugar.</p></div>${btn('+ Novo conjunto de exames','examForm()')}</div>${appData.examDraft?card('Cadastro em andamento',`<p>${esc(appData.examDraft.name||'Exames sem título')}</p>${btn('Continuar cadastro','resumeExam()','secondary')}`):''}<div class="exam-grid">${sorted(appData.examGroups).map(g=>card(esc(g.name),`<small>Coleta: ${date(g.collection||g.date)} · ${esc(g.place||'Local não informado')}</small><p>${g.results.length} resultados</p><p class="small">Solicitado por: ${esc(g.requester||'não informado')}<br>Avaliado por: ${esc(g.reviewer||'ainda não informado')}</p>${btn('Ver conjunto',`examDetail('${g.id}')`,'secondary')}${btn('Editar',`examForm('${g.id}')`,'plain')}`)).join('')}</div>${appData.exams.length?card('Registros de versões anteriores',appData.exams.map(e=>`<div class="item"><strong>${esc(e.name)}</strong><p>${esc(e.value)} ${esc(e.unit)}</p>${btn('Organizar em um conjunto',`convertOldExam('${e.id}')`,'plain')}</div>`).join('')):''}${!appData.examGroups.length&&!appData.exams.length?empty('Crie “Exames gerais” e adicione glicemia, hemograma, colesterol ou outros resultados do laudo.'):''}`}
function newExamResult(){return{id:uid(),name:'',value:'',unit:'',reference:''}}
function examForm(id=null){if(!id&&appData.examDraft){resumeExam();return}examDraft=id?clone(appData.examGroups.find(g=>g.id===id)):{id:uid(),date:stamp(),name:'Exames gerais',collection:day(),expected:'',received:'',reviewed:'',place:'',requester:'',reviewer:'',note:'',recommendations:'',results:[newExamResult()]};examEditor()}
function resumeExam(){examDraft=clone(appData.examDraft);if(examDraft)examEditor()}
function stashExam(){if(!examDraft||!$('#f_examtitle'))return;for(const[k,id]of Object.entries({name:'examtitle',collection:'collection',expected:'expected',received:'received',reviewed:'reviewed',place:'place',requester:'requester',reviewer:'reviewer',note:'examnote',recommendations:'recommendations'}))examDraft[k]=$('#f_'+id)?.value||'';for(let i=0;i<examDraft.results.length;i++)for(const k of ['name','value','unit','reference'])examDraft.results[i][k]=$('#f_result_'+i+'_'+k).value;appData.examDraft=clone(examDraft);accounts[accountId].data=appData;persist()}
function examEditor(){const g=examDraft;form('Conjunto de exames',field('examtitle','Título','text',g.name,'required maxlength="100" placeholder="Exames gerais"')+field('place','Laboratório / local da coleta','text',g.place,'maxlength="150"')+`<div class="grid"><div>${field('requester','Médico que solicitou','text',g.requester,'maxlength="120"')}</div><div>${field('reviewer','Médico que avaliou','text',g.reviewer,'maxlength="120"')}</div></div><div class="grid"><div>${field('collection','Data da coleta / realização','date',g.collection,'required')}</div><div>${field('expected','Previsão de resultado','date',g.expected)}</div><div>${field('received','Data de retirada / recebimento','date',g.received)}</div><div>${field('reviewed','Data da avaliação médica','date',g.reviewed)}</div></div><h3>Resultados do laudo</h3><p class="small muted">Unidade é a medida do resultado, como mg/dL ou %. Referência é a faixa informada no laudo, não o prazo de entrega. Copie os dados sem interpretar pelo aplicativo.</p>${g.results.map((r,i)=>`<section class="exam-result"><div class="row"><h3>Resultado ${i+1}</h3>${btn('Retirar',`stashExam();examDraft.results.splice(${i},1);examEditor()`,'plain')}</div>${field('result_'+i+'_name','Nome do exame','text',r.name,'required maxlength="120" placeholder="Glicemia, hemoglobina, colesterol…"')}${field('result_'+i+'_value','Resultado informado','text',r.value,'required maxlength="500" placeholder="Copie o resultado numérico ou descritivo"')}<div class="grid"><div>${field('result_'+i+'_unit','Unidade de medida (opcional)','text',r.unit,'maxlength="40" placeholder="mg/dL, g/dL, %, mUI/L…"')}</div><div>${field('result_'+i+'_reference','Faixa de referência do laudo (opcional)','text',r.reference,'maxlength="200"')}</div></div></section>`).join('')}${btn('+ Adicionar outro exame',"stashExam();examDraft.results.push(newExamResult());examEditor()",'secondary full')}${area('examnote','Como foi / observações',g.note)}${area('recommendations','Recomendações informadas pelo médico',g.recommendations)}${btn('Descartar este rascunho','discardExamDraft()','plain full')}`,()=>{stashExam();const x=clone(examDraft);if(!x.name.trim()||!x.results.length||x.results.some(r=>!r.name.trim()||!r.value.trim()))throw Error('Preencha o título e ao menos um resultado.');x.date=x.collection+'T12:00';if(change(d=>{const i=d.examGroups.findIndex(g=>g.id===x.id);if(i>=0)d.examGroups[i]=x;else d.examGroups.push(x);d.examDraft=null})){examDraft=null;closeModal();go('exams')}},'Salvar conjunto de exames');$('#entryForm').dataset.draft='exam';appData.examDraft=clone(examDraft);persist()}
function discardExamDraft(){confirmBox('Descartar cadastro em andamento?','Conjuntos já salvos serão preservados.',()=>{examDraft=null;change(d=>d.examDraft=null);closeModal();render()})}
function examDetail(id){const g=appData.examGroups.find(x=>x.id===id);modal(esc(g.name),`<p>${esc(g.place||'Laboratório não informado')}</p><div class="grid"><p class="small">Coleta: ${date(g.collection)}<br>Previsão: ${date(g.expected)}<br>Recebido: ${date(g.received)}</p><p class="small">Solicitado por: ${esc(g.requester)}<br>Avaliado por: ${esc(g.reviewer)}<br>Avaliação: ${date(g.reviewed)}</p></div>${g.results.map(r=>`<div class="exam-result"><h3>${esc(r.name)}</h3><p>${esc(r.value)} ${esc(r.unit)}</p><small>Referência do laudo: ${esc(r.reference||'não informada')}</small></div>`).join('')}<h3>Observações</h3><p style="white-space:pre-wrap">${esc(g.note)}</p><h3>Recomendações registradas</h3><p style="white-space:pre-wrap">${esc(g.recommendations)}</p>${btn('Editar conjunto',`examForm('${id}')`,'full')}${btn('Excluir conjunto',`deleteExamGroup('${id}')`,'plain full')}`)}
function deleteExamGroup(id){confirmBox('Excluir conjunto de exames?','Este conjunto e seus resultados serão excluídos.',()=>{if(change(d=>d.examGroups=d.examGroups.filter(x=>x.id!==id))){closeModal();render()}})}
function convertOldExam(id){const e=appData.exams.find(x=>x.id===id);examDraft={id:uid(),date:e.date,name:e.name,collection:e.date.slice(0,10),expected:'',received:'',reviewed:'',place:'',requester:'',reviewer:'',note:'Registro copiado da versão anterior. O original permanece no histórico.',recommendations:'',results:[{id:uid(),name:e.name,value:e.value,unit:e.unit,reference:e.reference||''}]};examEditor()}

function labelDoseMath(totalMg,totalMl,doseMg,capacity){if(![totalMg,totalMl,doseMg].every(x=>Number.isFinite(x)&&x>0))throw Error('Preencha quantidades positivas conforme o rótulo e a orientação recebida.');const concentration=totalMg/totalMl,r=syringeMath(doseMg,concentration,capacity);return{...r,concentration,capacityMg:capacity/100*concentration}}
function syringeCalculator(){const d=appData.settings.syringeLabel||(appData.demo?{totalMg:15,totalMl:.5,doseMg:3,capacity:30,division:1}:{});form('Dose e marcação na seringa',`<p>Informe o rótulo uma vez. A marcação depende da proporção entre medicamento e líquido.</p><div class="grid"><div>${field('totalMg','Quantidade indicada no rótulo (mg)','number',d.totalMg||'','required min="0.000001" step="any" placeholder="Ex.: 15"')}</div><div>${field('totalMl','Volume correspondente no rótulo (ml)','number',d.totalMl||'','required min="0.000001" step="any" placeholder="Ex.: 0,5"')}</div></div><small>Exemplo de leitura: “15 mg/0,5 ml”. Use os dois valores juntos. Não informe diluições estimadas.</small>${field('doseMg','Dose por aplicação (mg)','number',d.doseMg||'','required min="0.000001" step="any" placeholder="Quanto você usa em cada aplicação"')}<small>É a quantidade por vez, conforme orientação atual. O aplicativo não aumenta a dose.</small>${select('capacity','Tamanho da seringa — escala U-100',[[30,'Até 30 unidades · 0,3 ml'],[50,'Até 50 unidades · 0,5 ml'],[100,'Até 100 unidades · 1 ml']],d.capacity||30)}${select('division','Menor divisão marcada na sua seringa',[[1,'1 unidade'],[.5,'0,5 unidade'],[2,'2 unidades']],d.division||1)}${check('labelConfirmed','Conferi o rótulo, a dose orientada e a escala U-100 da seringa',false)}<div id="labelResult">${syringeSvg(null,d.capacity||30)}</div><p class="small muted">Trocar a capacidade de 100 para 30 unidades não muda o significado da marca 10 quando ambas são U-100. A graduação física pode ser diferente.</p><a class="source-link" href="https://www.fda.gov/drugs/human-drug-compounding/fda-alerts-health-care-providers-compounders-and-patients-dosing-errors-associated-compounded" target="_blank" rel="noopener">Referência sobre concentração e unidades: FDA ↗</a>`,v=>{if(!v.labelConfirmed)throw Error('Confirme os dados do rótulo e a escala da seringa.');const r=labelDoseMath(+v.totalMg,+v.totalMl,+v.doseMg,+v.capacity),fits=Math.abs(r.ui/+v.division-Math.round(r.ui/+v.division))<1e-7;$('#labelResult').innerHTML=`<div class="syringe-result"><small>Equivalência calculada com os dados informados</small><strong>${fmt(+v.doseMg,6)} mg → ${fmt(r.ui,6)} unidades</strong><p>${fmt(+v.totalMg,6)} mg em ${fmt(+v.totalMl,6)} ml · concentração ${fmt(r.concentration,6)} mg/ml</p>${syringeSvg(r.ui,+v.capacity,+v.division)}<p>${fits?'O resultado coincide matematicamente com a graduação informada.':'O resultado fica entre as marcas desta graduação. Não arredonde pelo desenho; confirme a medida com o profissional.'}</p><small>Capacidade física desta seringa, nessa concentração: ${fmt(r.capacityMg,6)} mg. Isso não é uma dose máxima permitida.</small></div>`;change(a=>a.settings.syringeLabel={totalMg:+v.totalMg,totalMl:+v.totalMl,doseMg:+v.doseMg,capacity:+v.capacity,division:+v.division},'Dados do rótulo salvos para a próxima conferência.')},'Conferir marcação');for(const id of ['totalMg','totalMl','doseMg','capacity','division'])$('#f_'+id).addEventListener('input',()=>{$('#labelResult').innerHTML=syringeSvg(null,+$('#f_capacity').value);$('#formError').textContent=''});$('#f_labelConfirmed').addEventListener('change',()=>{$('#labelResult').innerHTML=syringeSvg(null,+$('#f_capacity').value)})}

