function moveInfo(s){return {...moveInfoV2(s),name:moveLabel(s),text:exerciseText(s)}}
function sourceCredit(r){return `<p class="small muted">Desenhos: DAREBEE · 200 Easy Workouts${r?' · página '+r.page:''}. Material original em inglês; nomes e orientações do aplicativo em português. <a href="https://darebee.com" target="_blank" rel="noopener">Conheça a fonte</a> · <button class="plain" onclick="downloadWorkoutPDF()">↓ PDF original</button></p>`}
function sourceImage(r,small=false){return `<img class="workout-source${small?' thumb':''}" src="${WORKOUT_IMAGES[r.page]}" width="744" height="1053" alt="Desenhos humanos da sequência ${esc(r.name)}, página ${r.page} do material DAREBEE" loading="lazy">`}
function catalogSvg(name){const r=WORKOUT_CATALOG.find(r=>r.steps.some(s=>s.name===name));return r?sourceImage(r,true):''}
function movementView(){if(activeRoutine)return routinePlayer();if(sub==='micro'){const picks=[WORKOUT_CATALOG[65],WORKOUT_CATALOG[103],WORKOUT_CATALOG[53]];return `<div class="v2-head"><div><h1>Uma pausa para se mover</h1><p class="muted">Escolha uma sequência e faça no seu ritmo.</p></div></div>${tabs([['catalog','200 treinos'],['micro','Pausas curtas'],['history','Meu histórico']],'catalog')}<div class="catalog-grid">${picks.map(r=>`<article class="routine-card">${sourceImage(r,true)}<h3>${esc(r.name)}</h3>${btn('Ver movimentos',`routineDetail('${r.id}')`,'secondary full')}</article>`).join('')}</div>${sourceCredit()}`}
return movementViewV2().replace('Tenho 5 minutos','Pausas curtas').replace('Desenhos próprios por família; títulos da fonte preservados.','Desenhos humanos do material original e instruções em português.')+(!activeRoutine&&sub!=='history'?sourceCredit():'')}
function catalogSearch(){catalogSearchV2();const e=$('#catalogResults');if(!e)return;let h=e.innerHTML;/* A imagem original substitui a antiga ilustração esquemática. */e.innerHTML=h}
function routineDetail(id){const r=WORKOUT_CATALOG.find(x=>x.id===id);modal(esc(r.name),`<span class="pill">Treino ${r.number} de 200 · ${esc(r.category)}</span><div class="workout-layout"><div>${sourceImage(r)}${sourceCredit(r)}</div><div><h3>Como fazer a sequência</h3><p class="small muted">Use o desenho à esquerda junto às etapas abaixo. As quantidades vêm da ficha, não de uma prescrição individual.</p>${r.notes?notice(esc(r.notes)):''}${r.steps.map((s,i)=>`<section class="exam-result"><strong>${i+1}. ${esc(moveLabel(s.name))}</strong><p><span class="pill">${stepAmount(s)}</span>${s.sets?' · '+s.sets+' séries · '+s.rest+' s de pausa':''}</p><p class="small">${esc(exerciseText(s.name))}</p></section>`).join('')}${r.rest?`<p class="small">Pausa entre voltas: até ${fmt(r.rest/60)} minuto(s).</p>`:''}${select('routineRounds','Voltas da sequência',r.levels.map((n,i)=>[n,n+' volta(s)'+(r.levels.length>1?' · nível '+(i+1):'')]),r.levels[0])}${!routineCompatible(r)?notice('Esta ficha inclui movimentos que você prefere evitar. Consulte as preferências para escolher outra.'):btn('Começar com acompanhamento',`startRoutine('${id}',+$('#f_routineRounds').value)`,'full')}<p class="small muted">Faça movimentos confortáveis e pare se sentir dor, tontura ou falta de ar fora do habitual.</p></div></div>`);$('#modal').classList.add('wide-dialog')}
function routinePlayer(){const a=activeRoutine,s=a.program[a.index],r=WORKOUT_CATALOG.find(x=>x.id===a.id);return `<div class="v2-head"><div><h1>${esc(a.name)}</h1><p class="muted">Etapa ${a.index+1} de ${a.program.length} · volta ${s.round} de ${a.rounds}</p></div><span class="pill" id="routineClock">${clock(Math.floor(a.elapsed))}</span></div><div class="workout-layout"><div class="card">${sourceImage(r)}${sourceCredit(r)}</div>${card('Seu movimento agora',`<h2>${esc(moveLabel(s.name))}</h2><div class="stat">${stepAmount(s)}</div>${s.otherSide?'<p>Repita do outro lado.</p>':''}<div id="stepClock" class="timer">${clock(s.kind==='sec'?Math.max(0,s.value-Math.floor(a.stepElapsed)):Math.floor(a.stepElapsed))}</div><p>${esc(exerciseText(s.name))}</p><p class="small muted">Avance ao concluir. O tempo não troca a etapa automaticamente.</p>${btn(a.paused?'Continuar':'Pausar','pauseRoutine()','secondary full')}${btn(a.index===a.program.length-1?'Concluir treino':'Concluí esta etapa →','nextRoutineStep()','full')}${btn('Encerrar e registrar o tempo feito','finishRoutine()','plain full')}<details><summary>Ver sequência completa</summary>${a.program.map((x,i)=>`<p class="small">${i<a.index?'✓':i===a.index?'→':'○'} ${esc(moveLabel(x.name))} · ${stepAmount(x)}</p>`).join('')}</details>`)}</div>`}
function downloadWorkoutPDFV4(){const chunks=[];for(let i=0;i<WORKOUT_PDF_BASE64.length;i+=32768){const s=atob(WORKOUT_PDF_BASE64.slice(i,i+32768));chunks.push(Uint8Array.from(s,c=>c.charCodeAt(0)))}const u=URL.createObjectURL(new Blob(chunks,{type:'application/pdf'})),a=document.createElement('a');a.href=u;a.download='200-easy-workouts.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(u),30000)}

