function recipeDetail(id){recipeDetailV2(id);$('#modalBody').innerHTML+=btn('Adicionar porção à montagem',`addRecipeToDraft('${id}')`,'secondary full')}
function addRecipeToDraft(id){const r=recipeBy(id);form('Adicionar prato à refeição',`<h3>${esc(r.name)}</h3>${field('parts','Quantas porções?','number',1,'required min="0.1" max="1000" step="0.1"')}`,v=>{if(!draftMeal)draftMeal={id:uid(),name:'Minha refeição',date:stamp(),items:[]};draftMeal.items.push(...scaledItems(r.items,+v.parts/r.yield).map(i=>({...i,recipeName:r.name})));persistDraft();mealEditor()},'Adicionar ingredientes à montagem')}
function reportBodyV3(days){const from=ago(-(days-1));const groups=appData.examGroups.filter(g=>g.date.slice(0,10)>=from&&g.date.slice(0,10)<=day());return reportBodyV2(days)+card('Conjuntos de exames',groups.map(g=>`<section class="exam-result"><h3>${esc(g.name)}</h3><p class="small">Coleta: ${date(g.collection)} · ${esc(g.place)}<br>Solicitado por: ${esc(g.requester)} · Avaliado por: ${esc(g.reviewer)}</p>${g.results.map(r=>`<p>${esc(r.name)}: ${esc(r.value)} ${esc(r.unit)} · referência do laudo: ${esc(r.reference)}</p>`).join('')}<p>${esc(g.note)}</p><p>Recomendações registradas: ${esc(g.recommendations)}</p></section>`).join('')||empty('Sem conjuntos no período.'))}
function validateBackupV3(b){const result=validateBackupV2(b),fail=s=>{throw Error('Backup inválido: '+s)},obj=x=>x&&typeof x==='object'&&!Array.isArray(x),str=(s,m=5000)=>typeof s==='string'&&s.length<=m,num=(v,min=0,max=1e10)=>typeof v==='number'&&Number.isFinite(v)&&v>=min&&v<=max;for(const a of Object.values(result.accounts)){const d=a.data;if(!Array.isArray(d.foodEdits)||d.foodEdits.length>FOODS.length||!Array.isArray(d.examGroups))fail('dados V3');const seen=new Set();for(const f of [...d.customFoods,...d.foodEdits]){if(!obj(f)||!str(f.id,100)||seen.has(f.id)||!str(f.name,200)||!str(f.source,300)||!str(f.measure,80)||!['g','ml','gota'].includes(f.unit)||!num(f.base,.1,5000)||!obj(f.micro)||!Array.isArray(f.tags))fail('cadastro de alimento');seen.add(f.id);if(d.foodEdits.includes(f)&&!FOODS.some(x=>x.id===f.id))fail('edição sem alimento original');for(const k of ['kcal','protein','carbs','fat','fiber'])if(!num(f[k],0,100000))fail('nutriente');if(f.missing&&(!Array.isArray(f.missing)||f.missing.some(k=>!['kcal','protein','carbs','fat','fiber'].includes(k))))fail('nutriente ausente');if(f.servings&&(!Array.isArray(f.servings)||!f.servings.length||f.servings.length>100||f.servings.some(s=>!obj(s)||!str(s.name,80)||!num(s.g,.1,5000))))fail('medida caseira')}
const foodIds=new Set([...FOODS,...d.customFoods].map(f=>f.id));if(d.mealDraft){const m=d.mealDraft;if(!obj(m)||!str(m.id,100)||!/^[-\w]+$/.test(m.id)||!str(m.name,100)||!Array.isArray(m.items)||m.items.length>300)fail('rascunho de refeição');for(const i of m.items){if(!obj(i)||!foodIds.has(i.foodId)||!num(i.qty,.000001,1e8)||!num(i.grams,.1,5000)||!str(i.name,200)||!str(i.measure,100)||!obj(i.micro)||!Array.isArray(i.tags))fail('ingrediente do rascunho');for(const k of ['kcal','protein','carbs','fat','fiber'])if(!num(i[k]))fail('valor do rascunho')}}
for(const g of [...d.examGroups,...(d.examDraft?[d.examDraft]:[])]){if(!obj(g)||!str(g.id,100)||!/^[-\w]+$/.test(g.id)||!str(g.name,100)||!Array.isArray(g.results)||g.results.length>300)fail('conjunto de exames');for(const key of ['place','requester','reviewer','note','recommendations','collection','expected','received','reviewed'])if(!str(g[key]))fail('campo do conjunto de exames');for(const r of g.results)if(!obj(r)||!str(r.id,100)||!/^[-\w]+$/.test(r.id)||!str(r.name,120)||!str(r.value,500)||!str(r.unit,40)||!str(r.reference,200))fail('resultado de exame')}}return result}
function syringeSvg(ui,capacity,division=1){const count=Math.round(capacity/division);return `<svg class="syringe" viewBox="0 0 540 145" role="img" aria-label="Seringa U-100 de ${capacity} unidades${ui===null?'':', equivalência '+fmt(ui,6)+' unidades'}"><path d="M16 75H70M70 63H85V87H70ZM85 48H445V100H85ZM445 38V110M449 72H505V80H449M508 57V96" fill="none" stroke="currentColor" stroke-width="2"/>${ui!==null?`<rect x="87" y="50" width="${356*ui/capacity}" height="48" fill="var(--blue)" opacity=".35"/><path d="M${87+356*ui/capacity} 46V103" stroke="var(--blue)" stroke-width="3"/>`:''}${Array.from({length:count+1},(_,i)=>{const v=i*division,x=87+v*356/capacity,major=capacity===100?v%10===0:v%5===0;return `<path d="M${x} 50v${major?20:10}" stroke="currentColor"/>${major?`<text x="${x}" y="32" text-anchor="middle" font-size="12" fill="currentColor">${v}</text>`:''}`}).join('')}<text x="265" y="131" text-anchor="middle" font-size="12" fill="currentColor">U-100 · ${capacity} unidades · divisão de ${fmt(division)} · ilustração</text></svg>`}
