const MEDITATION_IMAGE="assets/meditacao.png";
function emptyJourney(){return{position:0,lastVisit:'',visits:[],awards:[],history:[]}}
function defaultJourneyZone(){try{return Intl.DateTimeFormat().resolvedOptions().timeZone||'America/Sao_Paulo'}catch{return'America/Sao_Paulo'}}
function migrateData(d){migrateDataV3(d);if(!d.journey)d.journey=emptyJourney();if(!Array.isArray(d.meditations))d.meditations=[];if(!Array.isArray(d.careRewards))d.careRewards=[];if(!('meditationDraft'in d))d.meditationDraft=null;if(!d.settings.journeyZone)d.settings.journeyZone=defaultJourneyZone();if(!d.settings.celebrations)d.settings.celebrations={motion:true,sound:false};if(!d.settings.meditation)d.settings.meditation={goalType:'sessions',goal:3,volume:.12};d.schema=4;return d}
function changeV4(fn,msg='Salvo no seu dispositivo'){const before={water:sum(today(appData.water),'ml'),activity:appData.exercises.length+appData.workouts.length,med:appData.meditations.length};const ok=changeV3(fn,msg);if(ok)careRewardAudit(before);return ok}
function renderV4(){if(!appData)return;migrateData(appData);restoreMeditation();registerJourney();renderV3();if(['journey','meditation'].includes(route))$('#main').classList.remove('v2-flow');if(route==='journey')wireJourney();if(route==='meditation')wireMeditation();renderMeditationDock()}
function homeView(){return homeViewV3().replace('<div class="v2-stats">',`<div class="v4-home-grid">${journeySummary()}${meditationSummary()}</div><div class="v2-stats">`)}
function profileViewV4(){return profileViewV3().replace('<h1>Seu espaço</h1>',`<h1>Seu espaço</h1>${card('Minha jornada',menu('chart','Minha caminhada',"go('journey')")+menu('heart','Sua pausa e meditação',"go('meditation')")+menu('bell','Comemorações e fuso','journeySettings()'))}`)}
function closeModal(){closeModalV3();if(celebrationQueue.length&&!celebrationTimer)celebrationTimer=setTimeout(flushCelebration,400)}
function logout(saveDraft=true){if(saveDraft&&mSession){pauseMeditation(false);persistMeditation()}clearInterval(meditationTimer);mSession=null;meditationAccount=null;stopMeditationAudio();stopNarration();clearTimeout(journeyAnimTimer);journeyEvent=null;celebrationQueue=[];clearTimeout(celebrationTimer);celebrationTimer=null;clearTimeout(celebrationHideTimer);$('#celebrationBox').hidden=true;$('#confettiLayer').innerHTML='';$('#meditationDock').hidden=true;document.body.classList.remove('has-meditation');logoutV3(saveDraft)}
function reportBody(days){const start=ago(-(days-1)),ms=appData.meditations.filter(m=>m.date.slice(0,10)>=start&&m.date.slice(0,10)<=day());return reportBodyV3(days)+card('Pausas e meditação',`<p>${ms.length} sessões · ${fmt(ms.reduce((a,m)=>a+m.seconds,0)/60)} minutos registrados no período.</p>${ms.map(m=>`<div class="item small"><strong>${when(m.date)} · ${esc(meditationPractice(m.practiceId)?.name||'Pausa registrada')}</strong>${fmt(m.seconds/60)} min · ${esc(m.before||'')} → ${esc(m.after||'')}<p>${esc(m.note||'')}</p></div>`).join('')||empty('Sem sessões no período.')}`)}
function validateBackupV4(b){const out=validateBackupV3(b),fail=m=>{throw Error('Backup inválido: '+m)},obj=v=>v&&typeof v==='object'&&!Array.isArray(v),str=(s,n=5000)=>typeof s==='string'&&s.length<=n,int=(v,min,max)=>Number.isInteger(v)&&v>=min&&v<=max,iso=s=>str(s,10)&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&Number.isFinite(Date.parse(s+'T12:00:00Z'))&&new Date(s+'T12:00:00Z').toISOString().slice(0,10)===s;for(const a of Object.values(out.accounts)){const d=a.data,j=d.journey;if(!obj(j)||!int(j.position,0,100000)||!Array.isArray(j.visits)||j.visits.length>100000||j.visits.some((v,i)=>!iso(v)||(i>0&&v<=j.visits[i-1]))||!str(j.lastVisit,10)||j.lastVisit!==(j.visits.at(-1)||'')||!Array.isArray(j.awards)||!Array.isArray(j.history)||j.history.length>100000)fail('caminhada');if(new Set(j.awards.map(x=>x.mark)).size!==j.awards.length||j.awards.some(x=>!obj(x)||![...JOURNEY_MARKS,7,14,365,730,1095].includes(x.mark)||!iso(x.date)))fail('insígnia');if(j.history.some(h=>!obj(h)||!iso(h.date)||!int(h.from,0,100000)||!int(h.to,0,100000)||!int(h.missed,0,1000000)||!int(h.penalty,0,100000)))fail('histórico da caminhada');try{isoInZone(new Date(),d.settings.journeyZone)}catch{fail('fuso da caminhada')}const ce=d.settings.celebrations,me=d.settings.meditation;if(!obj(ce)||typeof ce.motion!=='boolean'||typeof ce.sound!=='boolean'||!obj(me)||!['sessions','minutes'].includes(me.goalType)||!int(me.goal,1,1000)||typeof me.volume!=='number'||me.volume<0||me.volume>1)fail('preferências de pausa');if(!Array.isArray(d.careRewards)||d.careRewards.length>100000||d.careRewards.some(r=>!obj(r)||!str(r.key,100)||!str(r.title,150)||!str(r.date,16)))fail('conquistas');if(new Set(d.careRewards.map(r=>r.key)).size!==d.careRewards.length)fail('conquistas repetidas');for(const s of [...d.meditations,...(d.meditationDraft?[d.meditationDraft]:[])]){if(!obj(s)||!str(s.id,100)||!/^[-\w]+$/.test(s.id)||!meditationPractice(s.practiceId)||!MEDITATION_POSES.some(p=>p[0]===s.pose)||!int(s.color,0,5)||!['none','rain','tones','lofi-calm','lofi-rain','lofi-night'].includes(s.audio)||typeof s.voice!=='boolean'||!str(s.before||'',100)||!str(s.after||'',100)||!str(s.note||'',5000))fail('sessão de meditação');if(s===d.meditationDraft){if(!Number.isFinite(s.elapsed)||s.elapsed<0||!int(s.duration,60,3600)||s.elapsed>s.duration||!str(s.createdAt,16))fail('pausa em andamento')}else if(!Number.isFinite(s.seconds)||s.seconds<=0||s.seconds>3600||typeof s.completed!=='boolean')fail('duração da pausa')}}return out}
