const MEDITATION_COLORS=[['Azul profundo','#526A8B'],['Verde musgo','#6F7D58'],['Lavanda','#A69AB9'],['Areia','#D8C5A5'],['Terracota','#C7927D'],['Cinza claro','#CFD4D6']];
const MEDITATION_POSES=[['chair','Na cadeira','Pés apoiados no chão ou em um suporte. Mãos sobre as coxas, ombros soltos. Use o encosto se ajudar.'],['floor','Na almofada','Pernas cruzadas de forma solta, quadril elevado e joelhos apoiados se necessário. Não force uma posição de lótus.'],['lying','Deitado com apoio','Apoios sob a cabeça e os joelhos são opcionais. Braços relaxados ao lado do corpo. Ajuste se algo incomodar.']];
const MEDITATION_PRACTICES=[
{id:'breath',name:'Respiração tranquila',subtitle:'Acompanhe um ciclo de cada vez.',minutes:3,color:0,steps:[['Encontre seu apoio','Sinta os pés ou o contato do corpo com a superfície. Relaxe um pouco a mandíbula.'],['Perceba a respiração','Observe o ar nas narinas ou o movimento do abdômen. Respire naturalmente, sem puxar o máximo de ar.'],['Volte com gentileza','Se perceber uma distração, reconheça e retorne à sensação escolhida. Não precisa esvaziar a mente.'],['Encerre devagar','Deixe a atenção se abrir aos sons do ambiente. Mova as mãos e retome no seu ritmo.']],source:'NHS · respiração para estresse',url:'https://www.nhs.uk/mental-health/self-help/guides-tools-and-activities/breathing-exercises-for-stress/',note:'Sem retenção de ar obrigatória. Se sentir tontura ou falta de ar, interrompa e volte à respiração habitual.'},
{id:'focus',name:'Um ponto de atenção',subtitle:'Sons, contato ou um foco visual.',minutes:3,color:2,steps:[['Escolha um foco','Observe um som, o contato das mãos ou a cor da tela. Você pode manter os olhos abertos.'],['Permaneça com curiosidade','Note pequenas mudanças sem tentar controlar o que aparece. Se olhar para a tela, pisque normalmente.'],['Perceba e retorne','Quando a mente se afastar, volte ao foco escolhido. Não é um teste de concentração perfeita.'],['Amplie a atenção','Perceba outros sons e os apoios do corpo antes de terminar.']],source:'NHS · mindfulness',url:'https://www.nhs.uk/mental-health/self-help/tips-and-support/mindfulness/',note:'Observar uma sensação na testa ou no couro cabeludo é opcional; não equivale a ativar um centro energético comprovado.'},
{id:'scan',name:'Percorrer o corpo',subtitle:'Observe sensações, sem precisar mudá-las.',minutes:5,color:1,steps:[['Pés e pernas','Perceba os apoios, a temperatura e o contato da roupa. Quase não sentir nada também é válido.'],['Quadril e tronco','Note onde seu corpo está sustentado. Observe o movimento do peito e do abdômen sem aumentar a respiração.'],['Mãos e braços','Perceba a posição das mãos, dos braços e dos ombros. Você pode ajustar a postura.'],['Rosto e cabeça','Observe a mandíbula, os olhos e a testa. Não precisa produzir uma sensação especial.'],['Corpo e ambiente','Perceba o corpo como um todo e volte aos sons ao redor.']],source:'NHS · exercícios MBSR',url:'https://www.guysandstthomas.nhs.uk/health-information/mindfulness-based-stress-reduction-mbsr/mbsr-exercises',note:'Pule uma região desconfortável ou escolha um foco externo. Não é necessário insistir na dor.'},
{id:'muscle',name:'Perceber e soltar',subtitle:'Uma pausa para a tensão muscular.',minutes:5,color:3,steps:[['Mãos','Feche as mãos suavemente por cerca de três segundos, solte e observe. Não prenda o ar.'],['Ombros','Eleve os ombros só um pouco e depois solte. Pule se houver dor ou restrição.'],['Pés','Pressione os pés levemente contra o chão e solte. Evite força máxima e joelhos travados.'],['Rosto','Deixe os dentes sem apertar e a expressão mais solta. Não force contrações no pescoço.'],['Descanso','Fique um momento apenas percebendo os apoios. Não é obrigatório notar uma grande diferença.']],source:'NCCIH · técnicas de relaxamento',url:'https://www.nccih.nih.gov/health/relaxation-techniques-what-you-need-to-know',note:'Faça cada contração leve uma vez, depois descanse durante o restante da etapa. Pule áreas doloridas ou lesionadas.'},
{id:'wave',name:'Onda de renovação',subtitle:'Uma visualização que acompanha você.',minutes:5,color:0,steps:[['Escolha uma imagem','Imagine uma luz suave, água morna ou uma sensação de espaço. “Energia” pode ser sua metáfora pessoal.'],['Descendo','Ao inspirar naturalmente, imagine a onda descendo da cabeça aos pés. Pode levar vários ciclos; não force a respiração.'],['Subindo','Ao expirar, imagine o caminho dos pés à cabeça, como uma metáfora de soltar a tensão. Não é preciso prender o ar.'],['Retorne ao presente','Deixe a imagem desaparecer e perceba os contatos reais do corpo com a superfície.']],source:'VA · imaginação guiada',url:'https://www.va.gov/WHOLEHEALTHLIBRARY/tools/Guided-Imagery.asp',note:'Visualização, não desintoxicação. O ar não percorre os membros nem sai pela cabeça. Roteiro adaptado, sem promessa de renovar tecidos.'},
{id:'memory',name:'Uma lembrança que acolhe',subtitle:'Um instante bom, sem exigir felicidade.',minutes:3,color:4,steps:[['Escolha uma cena','Lembre de um passeio, de uma conversa ou de um momento carinhoso. Não precisa ser a melhor memória da sua vida.'],['Perceba os detalhes','Que sons, cores e gestos faziam parte da cena? Observe o que conseguir recordar, sem exigir nitidez.'],['Um gesto opcional','Se quiser, encoste polegar e indicador levemente enquanto respira naturalmente. O gesto serve apenas como lembrete pessoal.'],['Volte ao ambiente','Solte as mãos e perceba o que está ao redor. Se a lembrança trouxer dor, troque por uma cena neutra ou interrompa.']],source:'Speer e Delgado · memórias positivas',url:'https://pubmed.ncbi.nlm.nih.gov/31482135/',note:'A pesquisa com memórias não comprova que o gesto dos dedos restaure felicidade instantaneamente ou trate tristeza.'},
{id:'color',name:'Uma cor para acompanhar',subtitle:'Escolha pelo conforto pessoal.',minutes:3,color:2,steps:[['Observe','Olhe para a cor escolhida sem fixar o olhar à força. Pisque normalmente e ajuste o brilho.'],['Imagine, se quiser','Você pode fechar os olhos e imaginar essa cor. Não precisa formar uma imagem perfeita.'],['Retorne','Se a atenção se afastar, volte à cor, à respiração habitual ou a um som.'],['Compare sua experiência','Observe se foi confortável. Outra cor ou nenhuma cor também são opções.']],source:'Elliot · cor e funcionamento psicológico',url:'https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2015.00368/full',note:'Cores são preferências e focos de atenção. Não prometemos um efeito clínico específico para cada tonalidade.'}
];
function meditationPractice(id){return MEDITATION_PRACTICES.find(p=>p.id===id)}
function posePicture(id,cls=''){const pose=MEDITATION_POSES.find(p=>p[0]===id)||MEDITATION_POSES[0],box={chair:'20 35 510 720',floor:'585 100 425 580',lying:'1030 420 910 290'}[pose[0]];return `<div class="med-pose ${pose[0]} ${cls}"><svg viewBox="${box}" role="img" aria-label="${esc(pose[1]+': '+pose[2])}"><image href="${MEDITATION_IMAGE}" width="1942" height="809"/></svg></div>`}

const JOURNEY_MARKS=[30,60,90,120,150,180,210,240,270,300,330,366];
const JOURNEY_NAMES={7:'Primeiros passos',14:'Minha rotina',30:'Um mês de passos',60:'Seguindo meu caminho',90:'Constância',180:'Meio ano de passos',365:'Meu primeiro ano',730:'Dois anos de passos',1095:'Três anos de passos'};
const TRAIL_COLORS=['#28766C','#466E94','#796B91','#A5702D','#94647C','#457E88'];
let journeyEvent=null,journeyRangeStart=0,journeyShowAll=false,journeyAnimTimer=null;
function isoInZone(now,zone){const p=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);return ['year','month','day'].map(k=>p.find(x=>x.type===k).value).join('-')}
function dateOrdinal(s){return Math.floor(Date.parse(s+'T12:00:00Z')/86400000)}
function journeyDay(now=new Date()){return isoInZone(now,appData.settings.journeyZone)}
function journeyTransitionV4(j,now){if(j.lastVisit&&now<=j.lastVisit)return null;const missed=j.lastVisit?Math.max(0,dateOrdinal(now)-dateOrdinal(j.lastVisit)-1):0,penalty=Math.floor(missed/7),from=j.position,to=penalty?Math.max(0,from-penalty):from+1;const next={...j,position:to,lastVisit:now,visits:[...j.visits,now],awards:[...j.awards],history:[...j.history,{date:now,from,to,missed,penalty:Math.min(from,penalty)}]};const earned=[];if(!penalty)for(const mark of JOURNEY_MARKS)if(from<mark&&to>=mark&&!next.awards.some(a=>a.mark===mark)){next.awards.push({mark,date:now});earned.push(mark)}return {next,event:{date:now,from,to,missed,penalty:Math.min(from,penalty),returning:penalty>0,earned}}}
function registerJourneyV4(){if(!appData)return;const t=journeyTransition(appData.journey,journeyDay());if(!t)return;const prev=appData.journey;appData.journey=t.next;accounts[accountId].data=appData;if(!persist()){appData.journey=prev;return}journeyEvent=t.event;if(t.event.earned.length)queueCelebration('Nova insígnia!',JOURNEY_NAMES[t.event.earned.at(-1)]+' · conquista permanente.','badge');else if(t.event.returning)queueCelebration('Bom te ver de volta.','Seu caminho continua aqui. Vamos juntos, um passo de cada vez.','return')}
function trailColor(n){return TRAIL_COLORS[Math.floor(Math.max(0,n-1)/30)%TRAIL_COLORS.length]}
function badgeArtV4(mark,locked=false){return `<span class="journey-badge ${locked?'locked':''}" style="--badge-color:${trailColor(mark)}" aria-hidden="true"><span>✦</span><b>${mark}</b></span>`}
function journeySummary(){const j=appData.journey,next=JOURNEY_MARKS.find(m=>m>j.position);return card('Minha caminhada',`<div class="row"><div><span class="eyebrow muted">POSIÇÃO NA TRILHA</span><div class="stat">${j.position} <small>passos</small></div></div>${badgeArt(j.awards.at(-1)?.mark||30,!j.awards.length)}</div><p class="small">${j.visits.length} dias de presença · ${j.awards.length} insígnias permanentes</p><p class="muted">${next?`${Math.max(0,next-j.position)} passos até o marco ${next}.`:'Seu caminho continua, um dia de cada vez.'}</p>${btn('Abrir meu caminho →',"go('journey')",'full')}`)}
function journeyViewV4(){const j=appData.journey;return `<div class="v2-head"><div><div class="eyebrow muted">MINHA CONSTÂNCIA</div><h1>Seu caminho continua.</h1><p class="muted">Cada presença é um passo. Suas conquistas ficam com você.</p></div>${btn('Preferências','journeySettings()','secondary')}</div><div class="journey-layout"><section class="card trail-card"><div class="row"><div><strong>Passo ${j.position}</strong><small class="block">${j.visits.length} dias registrados desde o início</small></div>${btn('◎ Meu ponto','centerJourney()','secondary')}</div><p class="small muted">Arraste com o mouse ou deslize com o dedo. Use também a rolagem e as setas do teclado.</p>${journeyEvent?.returning?'<div class="notice">Bom te ver de volta. Seu caminho continua aqui. Vamos juntos, um passo de cada vez.</div>':''}<div id="trailViewport" class="trail-viewport" tabindex="0" aria-label="Caminho de presença. Arraste ou use as setas para explorar."><div id="trailContent"></div></div><div class="row">${btn('← Trecho anterior','shiftJourney(-60)','plain')}${btn('Próximo trecho →','shiftJourney(60)','plain')}</div><small id="trailRange"></small></section><aside>${card('Suas insígnias',`<div class="badge-grid">${JOURNEY_MARKS.slice(0,7).map(n=>{const a=j.awards.find(x=>x.mark===n);return `<button class="badge-item" onclick="badgeDetail(${n})">${badgeArt(n,!a)}<strong>${JOURNEY_NAMES[n]}</strong><small>${a?'Conquistada em '+date(a.date):n+' dias de presença na trilha'}</small></button>`}).join('')}</div>${j.awards.some(a=>a.mark>365)?btn('Ver todas','allBadges()','plain full'):''}`)}${card('Como funciona',`<p class="small">O primeiro acesso do dia avança um ponto. A cada 7 dias completos de ausência, você recua um ponto, até o início.</p><p class="small">Ao retornar depois desse intervalo, a presença fica registrada no ponto após o recuo. O próximo dia volta a avançar.</p><p class="small">Os trechos mudam de cor a cada 30 passos. Insígnias e dias já registrados nunca são apagados pela ausência.</p><small>Dia contado em ${esc(appData.settings.journeyZone)}. Os marcos indicam passos registrados, não meses corridos.</small>`)}${appData.demo?card('Experimente a ideia',`<p class="small">Explore uma prévia separada, sem alterar os registros da demonstração.</p>${btn('Simular avanço e ausência','journeyPreview()','secondary full')}`):''}</aside></div>`}
function drawJourney(start){const j=appData.journey;journeyRangeStart=Math.max(0,start);const high=Math.max(j.position,...j.awards.map(a=>a.mark),...j.history.map(h=>h.from)),end=journeyRangeStart===0?Math.max(60,Math.ceil((high+30)/30)*30):journeyRangeStart+60,H=(end-journeyRangeStart)*51+180,x=n=>240+125*Math.sin(n*Math.PI/12),y=n=>H-90-(n-journeyRangeStart)*51;let paths='',dots='',tips='';for(let n=journeyRangeStart;n<end;n++){const m=n+.5;paths+=`<path d="M${x(n)} ${y(n)} Q${x(m)} ${y(m)} ${x(n+1)} ${y(n+1)}" fill="none" stroke="${n<j.position?trailColor(n+1):'var(--line)'}" stroke-width="5" stroke-dasharray="2 10" stroke-linecap="round"/>`}
for(let n=journeyRangeStart;n<=end;n++){const award=j.awards.find(a=>a.mark===n),isMark=JOURNEY_MARKS.includes(n);dots+=`<g class="trail-node" role="button" tabindex="0" aria-label="${n===0?'Início da jornada':'Passo '+n}${award?', insígnia conquistada':''}" onclick="trailPoint(${n})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();trailPoint(${n})}"><circle cx="${x(n)}" cy="${y(n)}" r="${isMark?22:14}" fill="${n<=j.position?trailColor(n):'var(--soft)'}" stroke="${award?trailColor(n):'var(--line)'}" stroke-width="${award?4:1}"/><text x="${x(n)}" y="${y(n)+4}" text-anchor="middle" font-size="${isMark?12:10}" fill="${n<=j.position?'white':'var(--muted)'}">${n===0?'0':n}</text>${award?`<text x="${x(n)+24}" y="${y(n)-14}" fill="${trailColor(n)}" font-size="20">✦</text>`:''}</g>`;if(n%10===4){const ts=[['Uma pausa para água?','water'],['Um pouco de movimento?','movement'],['Seu momento de pausa?','meditation'],['O que teve no seu prato?','food']][Math.floor(n/10)%4];tips+=`<button class="trail-tip" style="left:${x(n)>240?2:51}%;top:${y(n)-20}px" onclick="go('${ts[1]}')">${ts[0]}</button>`}}
const pos=j.position,vis=pos>=start&&pos<=end;$('#trailContent').innerHTML=`<svg class="trail-svg" viewBox="0 0 480 ${H}" preserveAspectRatio="none" aria-label="Trilha dos passos ${start} a ${end}">${paths}${dots}${vis?`<circle id="trailMarker" cx="${x(pos)}" cy="${y(pos)}" r="24" fill="none" stroke="var(--ink)" stroke-width="3" pointer-events="none"/>`:''}</svg>${tips}`;$('#trailContent').style.height=H+'px';$('#trailRange').textContent=`Trecho ${start} a ${end} · ${start===0?'Início da jornada':'Continue explorando os trechos anteriores'}`;return {x,y,H}}
function centerJourneyV4(animate=false){if(!$('#trailContent'))return;clearTimeout(journeyAnimTimer);const p=appData.journey.position,start=0,g=drawJourney(start),v=$('#trailViewport');v.scrollTop=g.y(p)-v.clientHeight/2;const e=journeyEvent;if(animate&&e&&e.from!==e.to&&appData.settings.celebrations.motion&&!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches){const m=$('#trailMarker');if(m){m.setAttribute('cx',g.x(e.from)) ;m.setAttribute('cy',g.y(e.from));if(e.returning)m.setAttribute('stroke','#8B9694');const begun=Date.now()+120;v.scrollTop=g.y(e.from)-v.clientHeight/2;const frame=()=>{const t=Math.min(1,Math.max(0,(Date.now()-begun)/1400)),ease=t*t*(3-2*t),point=e.from+(p-e.from)*ease;m.setAttribute('cx',g.x(point));m.setAttribute('cy',g.y(point));v.scrollTop=g.y(point)-v.clientHeight/2;if(t<1)journeyAnimTimer=setTimeout(frame,32)};journeyAnimTimer=setTimeout(frame,120)}}journeyEvent=null}
function shiftJourney(delta){drawJourney(Math.max(0,journeyRangeStart+delta));$('#trailViewport').scrollTop=delta>0?2600:100}
function wireJourneyV4(){centerJourney(true);const v=$('#trailViewport');let drag=null;v.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0||e.target.closest('button,.trail-node'))return;drag={y:e.clientY,top:v.scrollTop};v.setPointerCapture(e.pointerId);v.classList.add('dragging')});v.addEventListener('pointermove',e=>{if(drag)v.scrollTop=drag.top+drag.y-e.clientY});const end=()=>{drag=null;v.classList.remove('dragging')};v.addEventListener('pointerup',end);v.addEventListener('pointercancel',end)}
function trailPoint(n){if(JOURNEY_MARKS.includes(n))return badgeDetail(n);modal(n===0?'Início da jornada':'Passo '+n,`<p>${n<=appData.journey.position?'Esse ponto faz parte do seu caminho atual.':'Um próximo ponto da sua caminhada.'}</p><p class="small muted">As bolinhas mostram sua posição, não uma avaliação da sua saúde.</p>`)}
function badgeDetailV4(n){const a=appData.journey.awards.find(x=>x.mark===n);modal(JOURNEY_NAMES[n],`${badgeArt(n,!a)}<p>${a?'Conquistada em '+date(a.date)+'. Esta insígnia fica com você, mesmo se o caminho recuar.':'Alcance o marco de '+n+' passos na trilha para conquistar esta insígnia.'}</p>`)}
function allBadges(){modal('Todas as minhas insígnias',appData.journey.awards.map(a=>`<div class="item row">${badgeArt(a.mark)}<div><strong>${JOURNEY_NAMES[a.mark]}</strong><small>${date(a.date)}</small></div></div>`).join('')||empty('Seu primeiro marco está no caminho.'))}
function journeyPreview(){form('Prévia da caminhada',field('position','Posição antes da ausência','number',30,'required min="0" max="1095" step="1"')+field('absence','Dias completos sem acessar','number',14,'required min="0" max="3650" step="1"')+'<div id="journeyDemoResult"></div>',v=>{const from=+v.position,absence=+v.absence,to=absence>=7?Math.max(0,from-Math.floor(absence/7)):from+1;$('#journeyDemoResult').innerHTML=`<div class="notice"><strong>Passo ${from} → passo ${to}</strong><p>${absence>=7?'Bom te ver de volta. Seu caminho continua aqui. Vamos juntos, um passo de cada vez.':'Presença registrada. Mais um passo no seu caminho.'}</p><small>Insígnias preservadas. Simulação sem alterar dados.</small></div>`},'Simular')}

let celebrationQueue=[],celebrationTimer=null,celebrationHideTimer=null,audioContext=null,audioUnlocked=false;
function wantsMotion(){return !!appData?.settings.celebrations.motion&&!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches}
function queueCelebration(title,message,kind='care'){celebrationQueue.push({title,message,kind});if(!celebrationTimer)celebrationTimer=setTimeout(flushCelebration,450)}
function flushCelebration(){celebrationTimer=null;if(!appData||!celebrationQueue.length)return;if($('#modal').open){celebrationTimer=setTimeout(flushCelebration,700);return}const q=celebrationQueue.shift(),e=$('#celebrationBox');clearTimeout(celebrationHideTimer);e.hidden=false;e.innerHTML=`<div class="celebration-symbol" aria-hidden="true">${q.kind==='return'?'↶':q.kind==='badge'?'✦':'✓'}</div><div><strong>${esc(q.title)}</strong><p>${esc(q.message)}</p></div><button class="circle" onclick="dismissCelebration()" aria-label="Fechar comemoração">×</button>`;if(q.kind!=='return'){if(wantsMotion())showConfetti();if(appData.settings.celebrations.sound)playChime()}celebrationHideTimer=setTimeout(dismissCelebration,6500)}
function dismissCelebration(){clearTimeout(celebrationHideTimer);$('#celebrationBox').hidden=true;$('#confettiLayer').innerHTML='';if(celebrationQueue.length)celebrationTimer=setTimeout(flushCelebration,400)}
function showConfetti(){const e=$('#confettiLayer');e.innerHTML=Array.from({length:42},(_,i)=>`<i style="--x:${Math.random()*100}%;--delay:${Math.random()*.5}s;--drift:${(Math.random()-.5)*240}px;--spin:${Math.random()*720}deg;background:${TRAIL_COLORS[i%6]}"></i>`).join('');setTimeout(()=>e.innerHTML='',3600)}
function getAudioContext(){try{if(!audioContext){const A=window.AudioContext||window.webkitAudioContext;if(!A)return null;audioContext=new A()}if(audioContext.state==='suspended')audioContext.resume().catch(()=>{});return audioContext}catch{return null}}
function unlockAudio(){audioUnlocked=true;if(appData?.settings.celebrations.sound)getAudioContext()}
function playChime(){if(!audioUnlocked)return;const ctx=getAudioContext();if(!ctx)return;[523.25,659.25,783.99].forEach((hz,i)=>{const o=ctx.createOscillator(),g=ctx.createGain(),t=ctx.currentTime+i*.1;o.frequency.value=hz;o.type='sine';g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.035,t+.025);g.gain.exponentialRampToValueAtTime(.0001,t+.6);o.connect(g);g.connect(ctx.destination);o.start(t);o.stop(t+.65);o.onended=()=>{o.disconnect();g.disconnect()}})}
function grantCare(key,title,message,kind='care'){if(appData.careRewards.some(r=>r.key===key))return false;const ok=changeV3(d=>d.careRewards.push({key,title,date:stamp()}),'');if(ok)queueCelebration(title,message,kind);return ok}
function careRewardAudit(before){const dateNow=day(),water=sum(today(appData.water),'ml'),goal=hydrationGoal();if(water>before.water&&goal>0&&before.water<goal&&water>=goal)grantCare('water:'+dateNow,'Meta de água concluída!','Mais um cuidado com você. Sua meta de hoje foi alcançada.');const activity=appData.exercises.length+appData.workouts.length;if(activity>before.activity)grantCare('move:'+dateNow,'Movimento registrado!','Cada momento dedicado ao seu cuidado faz parte do caminho.');const med=appData.meditations.length;if(med>before.med){grantCare('med:first','Minha primeira pausa','Você reservou um momento para você. Esta conquista fica guardada.','badge');const p=meditationWeekProgress();if(p.value>=p.goal)grantCare('med:week:'+p.week,'Meta de pausas concluída!','Sua meta desta semana foi alcançada, no seu ritmo.','badge')}}
function journeySettings(){form('Seu caminho, do seu jeito',check('motion','Usar animações e confetes',appData.settings.celebrations.motion)+check('sound','Tocar som curto nas conquistas',appData.settings.celebrations.sound)+select('zone','Fuso para registrar a presença',Array.from(new Set([appData.settings.journeyZone,'America/Sao_Paulo','America/Manaus','America/Rio_Branco','America/Noronha','Europe/Lisbon','UTC'])),appData.settings.journeyZone)+notice('O acesso é contado por dia de calendário neste fuso. Alterar o fuso não cria outro passo em uma data já registrada. A preferência de movimento reduzido do dispositivo também é respeitada.')+btn('Experimentar som','unlockAudio();playChime()','secondary'),v=>{if(change(d=>{d.settings.celebrations={motion:!!v.motion,sound:!!v.sound};d.settings.journeyZone=v.zone})){closeModal();render()}},'Salvar preferências')}
document.addEventListener('pointerdown',unlockAudio,{passive:true});document.addEventListener('keydown',unlockAudio);

let mSession=null,meditationAccount=null,meditationTimer=null,meditationAudio=[],meditationStage=-1,meditationSaveTick=0;
function meditationWeekProgress(){const now=journeyDay(),d=new Date(now+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));const week=d.toISOString().slice(0,10),items=appData.meditations.filter(m=>m.date.slice(0,10)>=week&&m.date.slice(0,10)<=now),settings=appData.settings.meditation;return{week,value:settings.goalType==='sessions'?items.filter(m=>m.seconds>=60).length:items.reduce((n,m)=>n+m.seconds,0)/60,goal:settings.goal,unit:settings.goalType==='sessions'?'sessões':'minutos'}}
function meditationSummary(){const w=meditationWeekProgress();return card('Sua pausa',`<div class="row"><div><span class="eyebrow muted">NESTA SEMANA</span><div class="stat">${fmt(w.value,0)} <small>/ ${w.goal} ${w.unit}</small></div></div><span class="pause-symbol" aria-hidden="true">◌</span></div><progress max="${w.goal}" value="${Math.min(w.value,w.goal)}"></progress><p class="muted">Um momento para perceber como você está.</p>${btn(mSession?'Retomar minha pausa →':'Encontrar minha pausa →',"go('meditation')",'full')}`)}
function meditationView(){const tab=tabs([['practices','Praticar'],['prepare','Preparar meu espaço'],['history','Meus registros']],'practices');return `<div class="v2-head"><div><div class="eyebrow muted">SEU MOMENTO, SEU RITMO</div><h1>Uma pausa no caminho.</h1><p class="muted">Não precisa esvaziar a mente. Comece encontrando um apoio.</p></div>${btn('Minha meta','meditationGoal()','secondary')}</div>${tab}${sub==='prepare'?meditationPreparation():sub==='history'?meditationHistory():meditationPracticeView()}`}
function meditationPracticeView(){return `${mSession?meditationPlayer():`<div class="med-intro"><div><span class="eyebrow">CHEGUE COMO VOCÊ ESTÁ</span><h2>Alguns minutos para você.</h2><p>Escolha uma prática e ajuste a posição, o tempo, a cor e o som. Todos os roteiros estão em português.</p><p class="small muted">Olhos abertos ou fechados. Silêncio também é uma escolha.</p>${btn('Começar com 3 minutos',"configureMeditation('breath')")}</div>${posePicture('chair')}</div>`}<div class="med-practice-grid">${MEDITATION_PRACTICES.map((p,i)=>`<article class="card med-practice"><div class="med-card-top"><span class="med-practice-number" style="background:${MEDITATION_COLORS[p.color][1]};color:${p.color<2?'#fff':'#28343b'}">${String(i+1).padStart(2,'0')}</span><small>${p.minutes} min sugeridos</small></div><h2>${p.name}</h2><p class="muted">${p.subtitle}</p>${btn('Conhecer e praticar →',`configureMeditation('${p.id}')`,'secondary full')}</article>`).join('')}</div><div class="notice small">Os roteiros são adaptações educativas. Você pode ajustar a posição, abrir os olhos, trocar de foco ou parar se a prática trouxer desconforto. Não há obrigação de sentir calma.</div>`}
function meditationPreparation(){return `<div class="v2-head"><div><h2>Conforto antes de concentração.</h2><p class="muted">Escolha a posição que seu corpo tolera bem. Não existe uma postura obrigatória.</p></div></div><div class="med-pose-grid">${MEDITATION_POSES.map(p=>card(p[1],posePicture(p[0])+`<p>${p[2]}</p><small class="muted">Ilustração de apoio, não uma exigência de alinhamento perfeito.</small>`)).join('')}</div><div class="v2-grid">${card('Seu espaço',`<p><strong>Luz:</strong> suave e confortável, com o brilho da tela baixo se ajudar.</p><p><strong>Apoio:</strong> cadeira firme, almofada ou superfície confortável. Solte roupas apertadas e ajuste a temperatura.</p><p><strong>Som:</strong> silêncio, chuva sintetizada ou notas suaves. Use volume baixo; fones são opcionais.</p><p><strong>Começo:</strong> um a três minutos já permitem experimentar. Aumente apenas se fizer sentido para você.</p>`)}${card('Uma cor que combine com este momento',`<p>Experimente um foco visual simples. Escolha pelo conforto, sem associar uma cor a uma cura.</p><div class="med-colors">${MEDITATION_COLORS.map(([name,c])=>`<button onclick="colorMeditation(${MEDITATION_COLORS.findIndex(x=>x[0]===name)})" aria-label="Praticar com ${name}"><span style="background:${c}"></span><small>${name}</small></button>`).join('')}</div>`)}</div>${card('Quando a atenção se afastar',`<p>Perceba a distração e volte a um apoio: o ar nas narinas, os pés no chão, um som ou uma cor. Esse retorno faz parte da prática.</p><p>Imaginar uma onda ou uma lembrança é opcional. Não precisa sentir “energia” ou produzir uma imagem nítida. Se prestar atenção no corpo incomodar, prefira um foco externo.</p>`)}${card('De onde vêm as orientações',`<p class="small">Roteiros originais adaptados a partir das referências abaixo. As ilustrações foram criadas para este guia com auxílio de IA.</p>${MEDITATION_PRACTICES.map(p=>`<details class="item"><summary>${p.name}</summary><p>${p.note}</p><a href="${p.url}" target="_blank" rel="noopener noreferrer">${p.source} ↗</a></details>`).join('')}<p class="small muted">Técnicas de relaxamento podem ajudar algumas pessoas. Não substituem acompanhamento quando há sofrimento persistente.</p>`)}`}
function colorMeditation(c){configureMeditation('color',c)}
function localMeditationVoice(){try{return window.speechSynthesis?.getVoices().find(v=>v.localService&&/^pt(-|_)/i.test(v.lang))||null}catch{return null}}
function configureMeditation(id,color){if(mSession){modal('Sua pausa está guardada',`<p>Você tem uma sessão em andamento. Retome ou encerre essa sessão para começar outra.</p>${btn('Voltar à sessão',"closeModal();go('meditation','practices')",'full')}`);return}const p=meditationPractice(id);if(!p)return;form(p.name,`<p>${p.subtitle}</p><details class="item"><summary>Ver o roteiro e a referência</summary>${p.steps.map(([t,s])=>`<p><strong>${t}.</strong> ${s}</p>`).join('')}<p class="small muted">${p.note}</p><a href="${p.url}" target="_blank" rel="noopener noreferrer">${p.source} ↗</a></details>`+select('pose','Como quer se acomodar?',MEDITATION_POSES.map(p=>[p[0],p[1]]),'chair')+`<div id="medPosePreview">${posePicture('chair')}</div>`+select('minutes','Tempo da pausa',[[1,'1 minuto'],[3,'3 minutos'],[5,'5 minutos'],[10,'10 minutos'],[15,'15 minutos'],[20,'20 minutos'],[30,'30 minutos']],p.minutes)+select('color','Cor de companhia',MEDITATION_COLORS.map((c,i)=>[i,c[0]]),color??p.color)+`<div id="medColorPreview" class="med-color-preview" style="background:${MEDITATION_COLORS[color??p.color][1]}"></div>`+select('audio','Som ambiente',[['none','Silêncio'],['rain','Chuva suave · sintetizada'],['tones','Notas suaves · sintetizadas'],['lofi-calm','Lo-fi · piano tranquilo'],['lofi-rain','Lo-fi · chuva e acordes'],['lofi-night','Lo-fi · noite leve']],'none')+check('voice','Ler as etapas em voz alta',false)+`<p class="small muted">A narração usa uma voz local em português, quando disponível no aparelho. O roteiro sempre aparece escrito.</p>`+field('before','Como você está agora? (opcional)','text','','maxlength="100" placeholder="Cansado, tranquilo, curioso…"'),v=>{startMeditation({practiceId:id,pose:v.pose,duration:+v.minutes*60,color:+v.color,audio:v.audio,voice:!!v.voice,before:v.before||''})},'Iniciar minha pausa');$('#f_pose').onchange=()=>{$('#medPosePreview').innerHTML=posePicture($('#f_pose').value)};$('#f_color').onchange=()=>{$('#medColorPreview').style.background=MEDITATION_COLORS[+$('#f_color').value][1]};if(!localMeditationVoice()){$('#f_voice').disabled=true;$('#f_voice').checked=false}}
function restoreMeditation(){if(meditationAccount===accountId)return;clearInterval(meditationTimer);stopMeditationAudio();stopNarration();meditationAccount=accountId;mSession=appData.meditationDraft?{...clone(appData.meditationDraft),paused:true,last:Date.now()}:null;meditationStage=-1}
function persistMeditation(){if(!appData)return false;const previous=appData.meditationDraft;appData.meditationDraft=mSession?{...mSession,paused:true,last:0}:null;accounts[accountId].data=appData;if(!persist()){appData.meditationDraft=previous;return false}return true}
function startMeditation(options){if(mSession)return;const p=meditationPractice(options.practiceId);if(!p||!Number.isInteger(options.duration)||options.duration<60||options.duration>3600)throw Error('Escolha uma prática e um tempo válido.');mSession={id:uid(),createdAt:stamp(),elapsed:0,paused:true,last:Date.now(),note:'',after:'',...options};meditationAccount=accountId;if(!persistMeditation()){mSession=null;return}closeModal();go('meditation','practices');resumeMeditation()}
function meditationElapsed(){if(mSession&&!mSession.paused){const now=Date.now();mSession.elapsed=Math.min(mSession.duration,mSession.elapsed+Math.max(0,Math.min((now-mSession.last)/1000,5)));mSession.last=now}return mSession?.elapsed||0}
function medClock(seconds){seconds=Math.max(0,Math.ceil(seconds));return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')}
function currentMeditationStep(){const p=meditationPractice(mSession.practiceId);return Math.min(p.steps.length-1,Math.floor(mSession.elapsed/mSession.duration*p.steps.length))}
function meditationPlayer(){const s=mSession,p=meditationPractice(s.practiceId),step=currentMeditationStep();return `<section class="card med-player"><div class="row"><div><span class="eyebrow">SUA PAUSA EM ANDAMENTO</span><h2>${p.name}</h2></div><span class="pill" id="medState">${s.elapsed>=s.duration?'Tempo concluído':s.paused?'Pausada':'Em andamento'}</span></div><div class="med-player-grid"><div>${posePicture(s.pose)}<p class="small muted">${MEDITATION_POSES.find(p=>p[0]===s.pose)[2]}</p></div><div><div class="med-focus" style="background:${MEDITATION_COLORS[s.color][1]}"><span class="med-orbit ${!s.paused&&wantsMotion()?'moving':''}" aria-hidden="true"></span><span>${MEDITATION_COLORS[s.color][0]}</span></div><div class="med-timer" id="medClock" role="timer" aria-label="Tempo restante">${medClock(s.duration-s.elapsed)}</div><progress id="medProgress" max="${s.duration}" value="${s.elapsed}"></progress><div id="medStep" aria-live="polite"><small>Etapa ${step+1} de ${p.steps.length}</small><h3>${p.steps[step][0]}</h3><p>${p.steps[step][1]}</p></div><div class="med-controls">${btn(s.paused?'▶ Continuar':'Ⅱ Pausar','toggleMeditation()','secondary')}${btn('Encerrar e registrar','finishMeditation()')}</div><p class="small muted">Ao sair da página ou minimizar o app, a pausa fica guardada sem contar o tempo ausente.</p>${btn('Descartar esta sessão','discardMeditation()','plain')}</div></div></section>`}
function wireMeditation(){if(mSession)updateMeditationPlayer()}
function updateMeditationPlayer(){if(!mSession)return;const s=mSession,p=meditationPractice(s.practiceId),step=currentMeditationStep();if($('#medClock'))$('#medClock').textContent=medClock(s.duration-s.elapsed);if($('#medProgress'))$('#medProgress').value=s.elapsed;if($('#medState'))$('#medState').textContent=s.elapsed>=s.duration?'Tempo concluído':s.paused?'Pausada':'Em andamento';if($('#medStep')&&step!==meditationStage){$('#medStep').innerHTML=`<small>Etapa ${step+1} de ${p.steps.length}</small><h3>${p.steps[step][0]}</h3><p>${p.steps[step][1]}</p>`}if(step!==meditationStage&&!s.paused)narrateMeditation(step);meditationStage=step;renderMeditationDock()}
function resumeMeditation(){if(!mSession)return;if(mSession.elapsed>=mSession.duration)return finishMeditation();mSession.paused=false;mSession.last=Date.now();meditationStage=-1;clearInterval(meditationTimer);meditationTimer=setInterval(meditationTick,1000);startMeditationAudio();if(route==='meditation'){render()}updateMeditationPlayer()}
function pauseMeditation(refresh=true){if(!mSession)return;meditationElapsed();mSession.paused=true;clearInterval(meditationTimer);stopMeditationAudio();stopNarration();persistMeditation();if(refresh&&route==='meditation')render();else updateMeditationPlayer()}
function toggleMeditation(){if(!mSession)return;mSession.paused?resumeMeditation():pauseMeditation()}
function meditationTick(){if(!mSession||mSession.paused)return;meditationElapsed();if(mSession.elapsed>=mSession.duration){pauseMeditation();toast('Sua pausa chegou ao fim. Registre como foi quando quiser.');return}updateMeditationPlayer();if(++meditationSaveTick%5===0)persistMeditation()}
function renderMeditationDock(){const dock=$('#meditationDock');if(!dock)return;const visible=!!mSession&&!(route==='meditation'&&sub!=='history'&&sub!=='prepare');dock.hidden=!visible;document.body.classList.toggle('has-meditation',visible);if(visible)dock.innerHTML=`<button onclick="go('meditation','practices')"><strong>Sua pausa · ${medClock(mSession.duration-mSession.elapsed)}</strong><span>${mSession.paused?'Pausada':'Em andamento'} · voltar à sessão →</span></button>`}
function finishMeditation(){if(!mSession)return;pauseMeditation(false);if(mSession.elapsed<1){toast('Pratique um pouco antes de registrar, ou descarte a sessão.');return}form('Como foi sua pausa?',`<p>${meditationPractice(mSession.practiceId).name} · ${fmt(mSession.elapsed/60,1)} min praticados</p>`+field('after','Como você está agora? (opcional)','text',mSession.after||'','maxlength="100"')+area('note','Algo que quer guardar? (opcional)',mSession.note||'')+'<p class="small muted">Não precisa ter se sentido melhor. Este espaço é para registrar sua experiência.</p>',v=>saveMeditation(v),'Guardar minha pausa');for(const key of ['after','note'])$('#f_'+key).oninput=()=>{if(mSession){mSession[key]=$('#f_'+key).value;persistMeditation()}}}
function saveMeditation(v){if(!mSession||mSession.elapsed<1)return;const session=clone(mSession),record={id:session.id,date:session.createdAt,practiceId:session.practiceId,pose:session.pose,color:session.color,audio:session.audio,voice:session.voice,before:session.before,after:String(v.after||'').slice(0,100),note:String(v.note||'').slice(0,5000),seconds:session.elapsed,completed:session.elapsed>=session.duration};if(change(d=>{if(!d.meditations.some(m=>m.id===record.id))d.meditations.push(record);d.meditationDraft=null},'Sua pausa foi registrada.')){clearInterval(meditationTimer);mSession=null;stopMeditationAudio();stopNarration();closeModal();go('meditation','history')}}
function discardMeditation(){confirmBox('Descartar esta pausa?','O tempo desta sessão não será registrado. Suas outras pausas e conquistas continuam salvas.',()=>{pauseMeditation(false);const old=mSession;mSession=null;if(!persistMeditation()){mSession=old;return}closeModal();go('meditation','practices')},true)}
function meditationHistory(){const w=meditationWeekProgress(),list=sorted(appData.meditations),rewards=appData.careRewards.filter(r=>r.key.startsWith('med'));return `<div class="v2-grid">${meditationSummary()}${card('Registrar do seu jeito',`<p class="muted">Meditou fora do app? Também pode guardar esse momento aqui.</p>${btn('+ Registrar uma pausa','editMeditation()','secondary full')}<p class="small">A semana vai de segunda a domingo. Para a meta de sessões, contam pausas com pelo menos um minuto.</p>`)}</div>${card('Meu histórico',list.map(m=>`<div class="item row"><div><strong>${esc(meditationPractice(m.practiceId).name)}</strong><small>${when(m.date)} · ${fmt(m.seconds/60,1)} min${m.completed?' · tempo planejado concluído':''}</small><p class="small">${esc(m.before||'')} ${m.before&&m.after?'→':''} ${esc(m.after||'')}</p>${m.note?`<p class="small">${esc(m.note)}</p>`:''}</div>${btn('Editar',`editMeditation('${m.id}')`,'plain')}</div>`).join('')||empty('Sua primeira pausa pode começar com um minuto.'))}${rewards.length?card('Conquistas das suas pausas',rewards.map(r=>`<div class="item row"><span class="pause-symbol" aria-hidden="true">✦</span><div><strong>${esc(r.title)}</strong><small>${date(r.date.slice(0,10))} · conquista permanente</small></div></div>`).join('')):''}`}
function editMeditation(id){const m=appData.meditations.find(m=>m.id===id);form(m?'Editar pausa':'Registrar uma pausa',select('practiceId','Prática',MEDITATION_PRACTICES.map(p=>[p.id,p.name]),m?.practiceId||'breath')+field('date','Quando foi?','datetime-local',m?.date||stamp(),'required')+field('minutes','Minutos praticados','number',m?+(m.seconds/60).toFixed(2):3,'required min="0.02" max="60" step="0.01"')+field('before','Como estava antes? (opcional)','text',m?.before||'','maxlength="100"')+field('after','Como ficou depois? (opcional)','text',m?.after||'','maxlength="100"')+area('note','Seu registro (opcional)',m?.note||'')+(m?btn('Excluir registro',`deleteMeditation('${id}')`,'plain full'):''),v=>{const seconds=+v.minutes*60;if(!Number.isFinite(seconds)||seconds<=0||seconds>3600||!meditationPractice(v.practiceId)||!v.date)throw Error('Confira a prática, a data e a duração.');const rec={id:m?.id||uid(),date:v.date,practiceId:v.practiceId,pose:m?.pose||'chair',color:m?.color??0,audio:m?.audio||'none',voice:m?.voice||false,before:String(v.before||'').slice(0,100),after:String(v.after||'').slice(0,100),note:String(v.note||'').slice(0,5000),seconds,completed:m?.completed||false};if(change(d=>{const i=d.meditations.findIndex(x=>x.id===rec.id);i<0?d.meditations.push(rec):d.meditations.splice(i,1,rec)})){closeModal();go('meditation','history')}})}
function deleteMeditation(id){confirmBox('Excluir esta pausa?','A sessão será removida do histórico. Insígnias já conquistadas permanecem.',()=>{if(change(d=>{d.meditations=d.meditations.filter(m=>m.id!==id)})){closeModal();render()}})}
function meditationGoal(){const s=appData.settings.meditation;form('Uma meta que cabe na sua semana',select('goalType','Quero acompanhar',[['sessions','Sessões por semana'],['minutes','Minutos por semana']],s.goalType)+field('goal','Minha meta semanal','number',s.goal,'required min="1" max="1000" step="1"')+field('volume','Volume dos sons, de 0 a 100','number',Math.round(s.volume*100),'required min="0" max="100" step="1"')+'<p class="small muted">Você pode mudar sua meta. Sessões com um minuto ou mais contam para a meta de sessões; na meta de minutos, conta o tempo praticado.</p>',v=>{if(!Number.isInteger(+v.goal)||+v.goal<1||+v.goal>1000)throw Error('Use uma meta inteira entre 1 e 1000.');if(change(d=>{d.settings.meditation={goalType:v.goalType,goal:+v.goal,volume:Math.min(1,Math.max(0,+v.volume/100))}})){closeModal();if(mSession&&!mSession.paused)startMeditationAudio();render()}})}
function stopNarration(){try{window.speechSynthesis?.cancel()}catch{}}
function narrateMeditation(step){if(!mSession?.voice)return;const voice=localMeditationVoice();if(!voice||!window.SpeechSynthesisUtterance)return;stopNarration();const parts=meditationPractice(mSession.practiceId).steps[step],speech=new window.SpeechSynthesisUtterance(parts.join('. '));speech.voice=voice;speech.lang=voice.lang;speech.rate=.85;window.speechSynthesis.speak(speech)}
function stopMeditationAudioV4(){for(const n of meditationAudio){try{n.stop?.();n.disconnect?.()}catch{}}meditationAudio=[]}
function startMeditationAudioV4(){stopMeditationAudio();if(!mSession||mSession.audio==='none'||!appData.settings.meditation.volume)return;const ctx=getAudioContext();if(!ctx)return;const gain=ctx.createGain();gain.gain.value=appData.settings.meditation.volume*.12;gain.connect(ctx.destination);meditationAudio.push(gain);if(mSession.audio==='rain'){const buffer=ctx.createBuffer(1,ctx.sampleRate*3,ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;const src=ctx.createBufferSource(),filter=ctx.createBiquadFilter();src.buffer=buffer;src.loop=true;filter.type='lowpass';filter.frequency.value=1500;src.connect(filter);filter.connect(gain);src.start();meditationAudio.push(src,filter)}else for(const f of [174.61,220,261.63]){const osc=ctx.createOscillator();osc.type='sine';osc.frequency.value=f;osc.connect(gain);osc.start();meditationAudio.push(osc)}}

